INSERT INTO public.follows (follower_id, following_id, created_at)
INSERT INTO public.posts (user_id, celebrated_person_name, content, type, community_id, created_at)
VALUES
    ((SELECT id FROM public.profiles WHERE username = 'rafael.mendes'), '@ju.rocha', 'Ontem a @ju.rocha ficou meia hora depois do expediente me ajudando a debugar um problema de CSS que eu já tava prestes a desistir. Não era responsabilidade dela, não ia render nenhum crédito, mas ela sentou do meu lado (virtualmente) e resolveu em 15 minutos o que eu tava apanhando há 2 horas. Obrigado, Ju.', 'gratitude', NULL, '2026-03-16 18:30:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'ju.rocha'), '@rafael.mendes', 'O @rafael.mendes chegou hoje na daily com aquele componente pronto que todo mundo achava que ia levar a sprint inteira. E sabe o que mais? Ele documentou tudo. TUDO. Rafa, você me inspira a ser uma dev melhor.', 'inspiration', NULL, '2026-03-17 10:15:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'diego.design'), '@dona.lucia', 'Minha avó mora longe e eu não consigo visitar tanto quanto queria. Mas toda vez que ligo pra @dona.lucia (que nem é minha avó de sangue, é vizinha da minha mãe), ela pergunta se eu tô comendo direito, se tô dormindo bem, se tô feliz. Dona Lúcia, a senhora me faz falta sem nem saber.', 'memory', NULL, '2026-03-17 21:45:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'ricardo.alves'), '@thiago.costa', 'O @thiago.costa é estagiário há 4 meses. Hoje ele fez um code review no meu PR e encontrou um bug que eu, com 15 anos de experiência, não vi. Não ficou com medo de apontar, não pediu desculpa por discordar. Mandou a observação com respeito e estava certo. Esse moleque vai longe.', 'achievement', (SELECT id FROM public.communities WHERE name = 'time-tech'), '2026-03-18 16:20:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'vanessa.martins'), '@ana.beatriz', 'A @ana.beatriz tá passando por uma fase difícil pessoalmente (com a autorização dela pra eu contar isso). E mesmo assim, ela não deixou a peteca cair em nenhuma entrega. Mas o que eu quero reconhecer não é a produtividade — é a coragem de pedir ajuda quando precisou. Ana, obrigada por confiar em mim.', 'support', NULL, '2026-03-18 19:00:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'dona.lucia'), '@seu.antonio', 'O Antônio, meu vizinho de tantos anos... ontem ele apareceu aqui em casa com a prateleira da cozinha que tava caindo consertada. Eu nem tinha pedido, ele viu da última vez que veio tomar café e voltou com as ferramentas. Esse homem tem um coração que não cabe no peito.', 'gratitude', NULL, '2026-03-19 08:15:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'seu.antonio'), '@dona.lucia', 'A Lúcia fez bolo de fubá pra mim ontem. Sem motivo. Disse que lembrou que eu gostava. Às vezes a gente subestima o poder de alguém lembrar da gente.', 'gratitude', NULL, '2026-03-19 14:30:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'carlos.henrique'), '@pedro.augusto', 'O @pedro.augusto podia ter ido embora depois do primeiro tempo (o cara tinha acordo com a esposa pra voltar cedo). Mas ficou porque tava 3x2 e a gente precisava dele no gol. Resultado: tomou esporro em casa, mas salvou o jogo. Pedro, sua esposa tem razão, mas a gente te ama.', 'gratitude', (SELECT id FROM public.communities WHERE name = 'pelada-quinta'), '2026-03-19 22:10:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'marcos.vinicius'), '@camila.santos', 'A @camila.santos correu a primeira 10k dela hoje. Ela começou em janeiro sem conseguir fazer 1km sem parar. Quatro meses depois, cruzou a linha dos 10km com um sorriso que eu nunca vou esquecer. Cami, isso é só o começo.', 'achievement', (SELECT id FROM public.communities WHERE name = 'corre-sp'), '2026-03-20 11:00:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'thiago.costa'), '@ricardo.alves', 'O @ricardo.alves podia ser aquele tech lead que só cobra e delega. Mas toda vez que eu travo em algo, ele para o que tá fazendo e senta comigo pra entender o problema. Não dá a resposta pronta — me faz pensar. Tô aprendendo mais em 4 meses do que em 2 anos de faculdade.', 'admiration', (SELECT id FROM public.communities WHERE name = 'time-tech'), '2026-03-20 17:45:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'ana.beatriz'), '@vanessa.martins', 'Semana passada eu desabei numa call com a @vanessa.martins — chorei, contei tudo, fiz aquele papel que a gente tem vergonha de fazer no trabalho. Sabe o que ela fez? Não deu conselho. Não tentou resolver. Só ouviu. Às vezes ouvir é o maior presente que alguém pode dar.', 'gratitude', NULL, '2026-03-21 20:30:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'fernanda.lima'), '@rafael.mendes', 'Percebi um padrão no @rafael.mendes que quero registrar: em toda retro, ele fala pelo menos uma coisa positiva sobre alguém do time antes de falar de problemas. Parece pequeno mas muda o tom da conversa inteira. Comecei a fazer igual na minha squad.', 'inspiration', (SELECT id FROM public.communities WHERE name = 'time-tech'), '2026-03-21 09:40:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'patricia.nunes'), '@maria.helena', 'Conheci a @maria.helena numa roda de leitura. Ela tem 73 anos e lê mais que qualquer pessoa que eu conheço. Mas o que me impressiona não é a quantidade — é como ela escuta a opinião de todo mundo com a mesma atenção, sem nunca fazer ninguém se sentir menor. Que eu tenha essa elegância quando chegar lá.', 'admiration', NULL, '2026-03-22 15:20:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'camila.santos'), '@marcos.vinicius', 'O @marcos.vinicius me mandou mensagem no sábado de manhã pra saber se eu ia pro treino. Eu não ia — tava chovendo, tava com preguiça, tava inventando desculpa. Ele disse: ''Vem, eu te espero no km 3.'' E esperou. Marcos, obrigada por não me deixar desistir.', 'gratitude', (SELECT id FROM public.communities WHERE name = 'corre-sp'), '2026-03-22 19:00:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'pedro.augusto'), '@carlos.henrique', 'Quinta passada o @carlos.henrique errou um gol feito (sim, a bola ia entrar sozinha e ele conseguiu errar). Todo mundo zoou, claro. Mas depois do jogo ele me mandou áudio perguntando se eu tava bem porque me viu quieto. O cara erra gol mas não erra a leitura de um amigo. Prioridades certas.', 'support', (SELECT id FROM public.communities WHERE name = 'pelada-quinta'), '2026-03-23 23:15:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'lucas.ferreira'), '@thiago.costa', 'O @thiago.costa e eu entramos juntos como estagiários. Tinha tudo pra ser competição. Mas quando eu travei na primeira task, ele sentou comigo e dividiu as anotações dele. A gente poderia estar competindo por vaga e em vez disso tá crescendo junto. Valeu, Thiago.', 'support', (SELECT id FROM public.communities WHERE name = 'time-tech'), '2026-03-23 14:00:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'renata.campos'), '@ricardo.alves', 'Preciso falar do @ricardo.alves como líder técnico. Em 6 meses trabalhando com ele, nunca vi ele puxar crédito pra si. Quando o projeto vai bem, ele fala ''o time entregou''. Quando algo dá errado, ele fala ''eu não vi esse risco''. Liderança é isso.', 'admiration', (SELECT id FROM public.communities WHERE name = 'time-tech'), '2026-03-24 11:30:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'jorge.ribeiro'), '@edson.pereira', 'Lembrei hoje do Edson me ensinando a trocar pneu em 1987. A gente mal se conhecia, eu tinha acabado de me mudar pro bairro. Ele parou o carro dele, veio até o meu e ficou ali até eu conseguir sozinho. Quase 40 anos depois, @edson.pereira ainda é assim: para o que tá fazendo pra ajudar.', 'memory', NULL, '2026-03-24 07:30:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'maria.helena'), '@patricia.nunes', 'A @patricia.nunes me ensinou que nunca é tarde pra aprender. Ela que é professora virou minha aluna quando eu comecei a contar histórias na roda de leitura. Me ouvir com aqueles olhos atentos me fez acreditar que minhas memórias ainda importam.', 'inspiration', NULL, '2026-03-25 10:00:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'vanessa.martins'), '@fernanda.lima', 'Quero reconhecer a @fernanda.lima por algo que pouca gente viu: ela refez a dashboard de métricas 3 vezes porque não tava satisfeita com a clareza dos dados. Ninguém pediu, ninguém cobrou. Ela fez porque acredita que dado confuso desinforma. O resultado ficou impecável.', 'achievement', (SELECT id FROM public.communities WHERE name = 'time-tech'), '2026-03-25 16:00:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'edson.pereira'), '@seu.antonio', 'O Antônio carrega 70 anos nas costas e humildade no jeito. Outro dia tava ensinando o neto a lixar madeira com a mesma paciência que ensinou a mim 30 anos atrás. Não mudou. @seu.antonio é uma aula viva.', 'admiration', NULL, '2026-03-25 08:45:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'diego.design'), '@rafael.mendes', 'Entreguei um layout semana passada que eu achava bom. O @rafael.mendes olhou, ficou quieto uns segundos e disse: ''E se a gente invertesse a hierarquia visual aqui?'' Poderia ter dito ''não gostei''. Em vez disso, me deu uma direção melhor sem invalidar o meu trabalho. Faz diferença demais.', 'gratitude', (SELECT id FROM public.communities WHERE name = 'time-tech'), '2026-03-26 13:15:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'ricardo.alves'), '@renata.campos', 'A @renata.campos correu a maratona de São Paulo domingo. 42km. Sabe o que ela fez na segunda? Chegou no trabalho às 9 em ponto, com o joelho enfaixado e um sorriso. Quando perguntei se não queria folga, ela disse: ''Corri porque quis, trabalho porque gosto. Uma coisa não cancela a outra.'' Inspira.', 'inspiration', NULL, '2026-03-26 18:00:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'dona.lucia'), '@diego.design', 'Esse menino, o @diego.design — ligou pra mim outro dia só pra dizer que tava com saudade. Vocês não sabem o que isso significa pra quem mora sozinha. Ele não é da minha família, mas é da minha vida. Deus abençoe esse rapaz.', 'gratitude', NULL, '2026-03-27 09:20:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'ana.beatriz'), '@marcos.vinicius', 'O @marcos.vinicius sempre chega primeiro no treino e sai por último. Mas não é por performance — é porque ele espera todo mundo chegar e se certifica que todo mundo terminou bem. Sábado passado ficou esperando eu terminar meu pace (lento, eu sei) sem pressa nenhuma. Líder é quem espera.', 'admiration', (SELECT id FROM public.communities WHERE name = 'corre-sp'), '2026-03-27 17:30:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'carlos.henrique'), '@diego.design', 'O @diego.design não é o melhor jogador da pelada (desculpa, Diego). Mas é o cara que todo mundo quer no time. Sabe por quê? Porque ele comemora o gol dos outros como se fosse dele. Na quinta passada fez uma corrida de 30 metros pra abraçar o Lucas depois do gol. Esse espírito não se ensina.', 'inspiration', (SELECT id FROM public.communities WHERE name = 'pelada-quinta'), '2026-03-28 22:40:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'ju.rocha'), '@camila.santos', 'A @camila.santos tava insegura com a apresentação que ia fazer pro cliente. Me mandou o deck às 11 da noite pedindo opinião. Eu dei feedback honesto: 3 slides precisavam de ajuste. Sabe o que ela fez? Refez os 3 e me mandou de novo às 6 da manhã. Não pediu validação, pediu evolução. Camila, você é fera.', 'support', NULL, '2026-03-28 08:50:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'marcos.vinicius'), '@rafael.mendes', 'O @rafael.mendes completou 100 dias seguidos de treino hoje. Cem. Chuva, sol, viagem, criança doente — ele achou um jeito. Nem todo dia foi uma corrida longa, às vezes foram 15 minutos de esteira no hotel. Mas a consistência tá aí. Rafa, chapéu.', 'achievement', (SELECT id FROM public.communities WHERE name = 'corre-sp'), '2026-03-29 07:15:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'thiago.costa'), '@lucas.ferreira', 'O @lucas.ferreira tava travado num bug há 2 dias e com vergonha de pedir ajuda. Eu percebi porque ele tava quieto demais no Slack. Chamei ele num privado e a gente resolveu em 40 min. Lucas, nunca tenha vergonha de travar. Todo mundo trava. O importante é não travar sozinho.', 'support', NULL, '2026-03-29 15:30:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'seu.antonio'), '@jorge.ribeiro', 'Outro dia eu e o @jorge.ribeiro ficamos sentados no banco da praça sem falar nada por uns 20 minutos. Só ali. Depois ele disse: ''Tá bom assim.'' E tava. Nem toda amizade precisa de conversa. Algumas só precisam de presença.', 'memory', NULL, '2026-03-30 16:45:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'vanessa.martins'), '@ricardo.alves', 'Situação real: eu errei feio num alinhamento com stakeholder. Tipo, errei de verdade. O @ricardo.alves podia ter me exposto na reunião, podia ter corrigido na frente de todo mundo. Sabe o que ele fez? Me chamou no privado, me ajudou a montar um plano de correção e disse: ''A gente conserta junto.'' Liderança de verdade, pessoal.', 'gratitude', (SELECT id FROM public.communities WHERE name = 'time-tech'), '2026-03-30 19:15:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'fernanda.lima'), '@vanessa.martins', 'Faço uma observação sobre a @vanessa.martins — ela é a pessoa que mais lembra de aniversários, datas importantes e gostos pessoais de cada um do time. Parece bobagem, mas quando ela manda um ''feliz aniversário, Fer, sei que você gosta de café coado então deixei um pacote na sua mesa'', isso cria pertencimento.', 'admiration', NULL, '2026-03-31 10:30:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'camila.santos'), '@ju.rocha', 'Obrigada @ju.rocha por ter sido honesta comigo sobre a apresentação. Eu queria ouvir ''tá ótimo'' e você me deu algo melhor: ''tá bom, mas pode ser excelente''. Esse feedback me fez crescer mais do que qualquer elogio faria.', 'gratitude', NULL, '2026-03-31 12:00:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'pedro.augusto'), '@thiago.costa', 'O @thiago.costa tem 21 anos e já entende algo que muita gente de 40 não entende: que time é mais importante que ego. Na quinta passada ele tava jogando bem pra caramba, fazendo gol, dominando. Aí viu que o Lucas tava pra baixo e começou a passar a bola só pra ele. O Lucas fez o gol da virada. O sorriso do Thiago era maior que o do Lucas.', 'admiration', (SELECT id FROM public.communities WHERE name = 'pelada-quinta'), '2026-04-01 23:00:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'maria.helena'), '@dona.lucia', 'Eu e a @dona.lucia nos conhecemos em 1985, numa fila de banco. Ela tava com um bebê no colo e eu ajudei a segurar a bolsa. Quarenta anos depois, aquele bebê já é pai, e nós duas ainda tomamos café juntas quando dá. Algumas amizades não precisam de motivo pra começar — só de disposição pra continuar.', 'memory', NULL, '2026-04-01 09:00:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'rafael.mendes'), '@ricardo.alves', 'Uma coisa sobre o @ricardo.alves que ninguém fala: ele responde mensagem de todo mundo. Estagiário, PM, designer, o cara de infra que ninguém conhece. Todo mundo tem acesso a ele. Isso parece básico, mas eu já trabalhei em lugar onde tech lead era intocável. O Ricardo não é assim. E isso muda tudo.', 'admiration', NULL, '2026-04-02 11:40:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'renata.campos'), '@ana.beatriz', 'Quero celebrar a @ana.beatriz — ela começou a correr há 5 meses, como mãe solo, encaixando treino na hora do almoço. Sábado ela completou a primeira meia-maratona. 21km. Quando cruzou a linha, a primeira coisa que fez foi ligar pro filho. Ana, você ensina o Miguel pelo exemplo.', 'achievement', (SELECT id FROM public.communities WHERE name = 'corre-sp'), '2026-04-02 14:20:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'lucas.ferreira'), '@carlos.henrique', 'O @carlos.henrique me explicou git rebase umas 5 vezes. Cinco. Na quinta vez eu entendi (mais ou menos). Ele podia ter perdido a paciência na segunda. Mas em nenhum momento ele fez eu me sentir burro. Carlos, obrigado por tratar minha ignorância com respeito.', 'gratitude', NULL, '2026-04-03 16:50:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'edson.pereira'), '@carlos.henrique', 'Eu tenho 62 anos e jogo na pelada com moleque de 25. O @carlos.henrique nunca me tratou diferente. Pede passe, cobra marcação, comemora comigo. Não tem esse negócio de ''ah, o tio tá cansado''. Respeito é isso: me tratar como igual.', 'admiration', (SELECT id FROM public.communities WHERE name = 'pelada-quinta'), '2026-04-03 21:30:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'ju.rocha'), '@diego.design', 'O @diego.design recebeu um feedback duro sobre um layout na semana passada. Em vez de ficar na defensiva (que seria compreensível), ele veio no dia seguinte com 3 versões alternativas e perguntou: ''qual caminho vocês preferem?'' Maturidade profissional não tem nada a ver com idade.', 'admiration', (SELECT id FROM public.communities WHERE name = 'time-tech'), '2026-04-04 09:30:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'diego.design'), '@vanessa.martins', 'A @vanessa.martins percebeu que eu não tava bem antes de eu mesmo perceber. Me mandou mensagem: ''Quer tomar um café?'' Não perguntou o que eu tinha, não pressionou. Só ofereceu presença. Às vezes a gente só precisa de alguém que note.', 'support', NULL, '2026-04-04 20:00:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'patricia.nunes'), '@ana.beatriz', 'Eu tenho 47 anos e achava que era tarde demais pra começar a correr. Aí vi a @ana.beatriz — mãe solo, trabalhando integral, fazendo meia-maratona. Se ela encontrou tempo, qual é a minha desculpa? Me inscrevi na minha primeira 5k por causa dela.', 'inspiration', (SELECT id FROM public.communities WHERE name = 'corre-sp'), '2026-04-04 07:45:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'ricardo.alves'), '@carlos.henrique', 'O @carlos.henrique organiza a pelada toda quinta: reserva o campo, confirma quem vai, equilibra os times, traz a bola extra, lembra da água. Nunca pediu nada em troca. Nunca reclamou quando alguém fura em cima da hora. Carlos, você é o MVP fora de campo.', 'gratitude', (SELECT id FROM public.communities WHERE name = 'pelada-quinta'), '2026-04-05 12:30:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'ana.beatriz'), '@renata.campos', 'A @renata.campos fez uma coisa que me marcou: no 1:1 dela comigo, em vez de falar de entrega, perguntou como eu tava de verdade. E quando eu disse ''tô bem'', ela ficou em silêncio e esperou. Aí eu falei de verdade. Ela sabia que a primeira resposta nunca é a real. Que gestora.', 'admiration', (SELECT id FROM public.communities WHERE name = 'time-tech'), '2026-04-05 18:45:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'marcos.vinicius'), '@patricia.nunes', 'A @patricia.nunes quase desistiu no km 4 da primeira corrida dela. Eu tava do lado e só disse: ''Falta 1km. Vai andando se precisar, mas não para.'' Ela não parou. E depois me mandou mensagem: ''Você não me deixou desistir.'' Na real, ela que não desistiu. Eu só lembrei ela disso.', 'support', (SELECT id FROM public.communities WHERE name = 'corre-sp'), '2026-04-05 08:00:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'vanessa.martins'), '@ju.rocha', 'A @ju.rocha é mãe, designer, corredora e ainda arruma tempo pra fazer mentoria com duas juniores do time. Quando eu perguntei como ela dá conta, ela disse: ''Eu não dou. Eu escolho o que vou deixar cair e aceito.'' Essa honestidade é mais inspiradora que qualquer produtividade tóxica.', 'inspiration', NULL, '2026-04-06 13:00:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'jorge.ribeiro'), '@maria.helena', 'A @maria.helena escreveu um poema pro aniversário do meu neto. Ela nem conhece ele pessoalmente — conhece pelas histórias que eu conto. Mas o poema era tão certeiro que meu neto perguntou: ''Vô, a dona Helena me conhece?'' De certo modo, sim.', 'admiration', NULL, '2026-04-06 10:15:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'thiago.costa'), '@diego.design', 'Eu ia apagar uma mensagem no Slack porque achei que era boba demais. O @diego.design leu antes e respondeu: ''Essa ideia é boa, traz pro time.'' Aquela mensagem virou uma feature no produto. Diego, obrigado por ver valor no que eu quase joguei fora.', 'gratitude', NULL, '2026-04-06 16:30:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'dona.lucia'), '@vanessa.martins', 'Essa moça, a @vanessa.martins — me ligou dia desses pra saber se eu tava conseguindo mexer no app novo do banco. Ficou no telefone comigo 40 minutos. Quarenta! E com paciência, meu filho. Não deu risada, não ficou com pressa. Me explicou tudo como se eu fosse a pessoa mais importante do mundo naquele momento.', 'gratitude', NULL, '2026-04-07 07:50:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'rafael.mendes'), '@carlos.henrique', 'O @carlos.henrique mandou mensagem no grupo de pais da escola perguntando se alguém tinha um colchão extra pro filho do amigo dele que tava numa situação difícil. Em 2 horas ele tinha juntado colchão, roupa, material escolar e 3 marmitas. Ele não pediu crédito. Eu só soube porque tava no grupo. Carlos, isso é caráter.', 'support', NULL, '2026-04-07 20:10:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'camila.santos'), '@ana.beatriz', 'No treino de sábado a @ana.beatriz tava claramente num dia ruim. Mais lenta, sem energia, quase chorando. Eu diminuí meu ritmo e corri do lado dela sem falar nada. No km 3 ela disse: ''Obrigada por ficar.'' Não precisou de mais nada.', 'support', (SELECT id FROM public.communities WHERE name = 'corre-sp'), '2026-04-07 11:30:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'pedro.augusto'), '@edson.pereira', 'O @edson.pereira me contou que jogava no campinho do bairro dele quando era moleque — descalço, bola de meia. Quinta passada ele fez um gol de cobertura que eu juro que vi câmera lenta. 62 anos, senhoras e senhores. A bola não esquece quem ama ela.', 'memory', (SELECT id FROM public.communities WHERE name = 'pelada-quinta'), '2026-04-08 22:45:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'renata.campos'), '@marcos.vinicius', 'Obrigada @marcos.vinicius por ter me esperado no km 38 da maratona quando minhas pernas travaram. Você tava com pace pra fazer seu melhor tempo e largou isso pra ficar comigo. Perdi a conta de quantas vezes eu disse ''vai, eu me viro'' e você respondeu ''eu sei que se vira, mas eu fico.'' Amigo é isso.', 'gratitude', NULL, '2026-04-08 14:15:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'fernanda.lima'), '@camila.santos', 'A @camila.santos encontrou um bug em produção sexta às 17h. Todo mundo tava já saindo. Ela não só reportou — ela rastreou a causa raiz, documentou e sugeriu o fix. Na segunda a gente só precisou aprovar. QA com senso de dono é outra coisa.', 'inspiration', (SELECT id FROM public.communities WHERE name = 'time-tech'), '2026-04-08 09:50:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'seu.antonio'), '@edson.pereira', 'O @edson.pereira me levou no médico segunda-feira. Eu podia ter ido de ônibus, mas ele fez questão. Ficou na sala de espera 3 horas lendo jornal. Na volta paramos pra tomar um café. Não disse nada demais. Mas tava lá.', 'gratitude', NULL, '2026-04-09 15:00:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'carlos.henrique'), '@lucas.ferreira', 'O @lucas.ferreira fez o primeiro deploy dele em produção hoje. Sozinho. Sem ninguém segurando a mão. E funcionou de primeira. Eu lembro do primeiro deploy dele (que eu acompanhei de perto, de olho em tudo). Hoje ele não precisou de mim. Esse é o melhor elogio que um mentor pode receber: virar desnecessário.', 'achievement', (SELECT id FROM public.communities WHERE name = 'time-tech'), '2026-04-09 17:20:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'dona.lucia'), '@jorge.ribeiro', 'Eu e o @jorge.ribeiro fomos vizinhos por 25 anos antes dele se mudar pra Santos. Sabe o que eu mais sinto falta? Da buzina do carro dele de manhã, passando pra ir trabalhar. Era meu despertador. Ele nem sabia disso até eu contar agora.', 'memory', NULL, '2026-04-10 08:30:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'diego.design'), '@camila.santos', 'A @camila.santos fez uma coisa que ninguém mais faz: ela testou meu protótipo como usuária real, não como QA. Em vez de listar bugs, ela me disse: ''Aqui eu fiquei confusa, aqui eu sorri, aqui eu desisti.'' Esse tipo de feedback vale mais que 100 tickets no Jira.', 'gratitude', NULL, '2026-04-10 14:40:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'vanessa.martins'), '@patricia.nunes', 'Conheci a @patricia.nunes numa corrida e descobri que ela é professora de história. A gente começou falando de pace e terminou falando de como a educação no Brasil forma (ou deforma) cidadãos. Saí daquela conversa pensando diferente sobre 3 coisas. Pessoas que te fazem pensar são um presente.', 'admiration', NULL, '2026-04-11 18:20:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'ricardo.alves'), '@vanessa.martins', 'A @vanessa.martins discordou de mim numa reunião. Na frente de todo mundo. Com argumentos. E tava certa. Eu poderia ter levado pro lado pessoal, mas em vez disso levei pro lado profissional: a gente precisa de gente que discorda com respeito e dados. Obrigado por não concordar comigo, Van.', 'gratitude', NULL, '2026-04-11 11:00:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'maria.helena'), '@jorge.ribeiro', 'O @jorge.ribeiro consertou o portão da minha casa semana passada. Tem 76 anos e veio com a caixa de ferramentas na mão, como se fosse a coisa mais natural do mundo. Quando eu ofereci pagar, ele disse: ''Me paga com um café, dona Helena.'' O mundo precisa de mais Jorges.', 'gratitude', NULL, '2026-04-12 09:30:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'thiago.costa'), '@renata.campos', 'A @renata.campos fez uma coisa na retro que eu nunca tinha visto uma gestora fazer: ela admitiu que errou. Na frente do time todo. Disse: ''Eu deveria ter protegido vocês daquela demanda e não protegi.'' Ninguém ficou com menos respeito por ela. Pelo contrário.', 'admiration', (SELECT id FROM public.communities WHERE name = 'time-tech'), '2026-04-12 15:45:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'ana.beatriz'), '@camila.santos', 'Preciso agradecer a @camila.santos por ter corrido do meu lado sábado quando eu tava num dia péssimo. Ela não tentou me animar, não deu conselho, não perguntou o que eu tinha. Só ficou ali, no meu ritmo, em silêncio solidário. Às vezes o melhor apoio é simplesmente não ir embora.', 'gratitude', NULL, '2026-04-12 20:00:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'lucas.ferreira'), '@ricardo.alves', 'O @ricardo.alves me disse uma frase outro dia que eu colei no monitor: ''Você não precisa saber tudo, só precisa saber perguntar.'' Parece clichê, mas vindo de alguém com 15 anos de experiência que ainda pergunta coisas no Stack Overflow, tem outro peso.', 'inspiration', NULL, '2026-04-13 10:45:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'jorge.ribeiro'), '@dona.lucia', 'A @dona.lucia manda foto de bolo pra mim toda semana. Não é pra me fazer inveja — é pra eu sentir que ainda tô conectado com o bairro. Cada foto é um pedacinho de casa. Lúcia, obrigado por não me deixar ser um ex-vizinho.', 'gratitude', NULL, '2026-04-13 07:20:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'rafael.mendes'), '@marcos.vinicius', 'No dia que eu completei os 100 dias de treino, o @marcos.vinicius me deu um abraço e disse: ''Eu sabia que você ia conseguir. Você que não sabia.'' Cara, isso ficou ecoando na minha cabeça a semana inteira. Às vezes a gente precisa de alguém que acredite em nós antes da gente acreditar.', 'gratitude', (SELECT id FROM public.communities WHERE name = 'corre-sp'), '2026-04-13 19:30:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'edson.pereira'), '@thiago.costa', 'O @thiago.costa me chamou de ''mestre'' na pelada outro dia. Eu ri. Mas depois pensei: esse moleque trata todo mundo mais velho com respeito sem ser forçado. Não é educação de fachada. É caráter. Os pais desse garoto acertaram.', 'inspiration', (SELECT id FROM public.communities WHERE name = 'pelada-quinta'), '2026-04-14 21:00:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'camila.santos'), '@fernanda.lima', 'A @fernanda.lima tem um dom que eu invejo: ela pega dados frios e transforma em histórias que convencem. Aquela dashboard que ela refez? O PM usou na reunião de board e o C-level pediu mais. Fer, seus dados contam histórias melhores que muita série.', 'admiration', (SELECT id FROM public.communities WHERE name = 'time-tech'), '2026-04-14 11:15:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'pedro.augusto'), '@seu.antonio', 'Uma vez o @seu.antonio me ensinou a afiar faca com pedra. Eu, um DevOps que não sabe pregar prego, aprendendo a afiar faca com um carpinteiro aposentado num churrasco. Aquela tarde vale mais que qualquer workshop de team building que eu já fui.', 'memory', NULL, '2026-04-15 14:00:00+00'),
    ((SELECT id FROM public.profiles WHERE username = 'renata.campos'), '@fernanda.lima', 'Quero reconhecer algo que a @fernanda.lima fez discretamente: ela montou um doc com todos os processos do time que ninguém tinha documentado. Ninguém pediu. Ela viu que onboarding de gente nova era caótico e resolveu. Quando a Patrícia entrou na squad, teve tudo escrito. Isso é senso de time.', 'achievement', NULL, '2026-04-15 16:50:00+00');
INSERT INTO public.chains (name, description, highlight_type, is_memorias_vivas, created_by, created_at)
VALUES
    ('Quem te fez acreditar em você?', 'Conte sobre alguém que acreditou em você quando você mesmo não acreditava', 'inspiration', false, (SELECT id FROM public.profiles WHERE username = 'vanessa.martins'), '2026-03-26 20:30:00+00'),
    ('O conselho que eu carrego até hoje', 'Qual conselho alguém te deu que ainda guia suas decisões?', 'memory', true, (SELECT id FROM public.profiles WHERE username = 'seu.antonio'), '2026-03-24 10:00:00+00'),
    ('Um gesto pequeno que mudou seu dia', 'Às vezes não é o grande favor, é o detalhe. Conte sobre um gesto simples que fez diferença no seu dia.', 'gratitude', false, (SELECT id FROM public.profiles WHERE username = 'rafael.mendes'), '2026-03-21 12:30:00+00'),
    ('A pessoa que te ensinou sem saber', 'Alguém que te ensinou algo importante só pelo exemplo, sem nunca ter dado uma aula formal.', 'inspiration', false, (SELECT id FROM public.profiles WHERE username = 'ana.beatriz'), '2026-04-03 13:45:00+00');
