    ((SELECT id FROM public.profiles WHERE username = 'ju.rocha'), (SELECT id FROM public.posts WHERE content = 'O @marcos.vinicius me convidou pra correr minha primeira meia quando eu achava que 5k era meu limite' LIMIT 1), 'loved', (SELECT created_at FROM public.posts WHERE content = 'O @marcos.vinicius me convidou pra correr minha primeira meia quando eu achava que 5k era meu limite' LIMIT 1) + interval '3.7 hours'),
