    ((SELECT id FROM public.profiles WHERE username = 'ana.beatriz'), (SELECT id FROM public.posts WHERE content = 'O @marcos.vinicius me convidou pra correr minha primeira meia quando eu achava que 5k era meu limite' LIMIT 1), 'loved', (SELECT created_at FROM public.posts WHERE content = 'O @marcos.vinicius me convidou pra correr minha primeira meia quando eu achava que 5k era meu limite' LIMIT 1) + interval '25.6 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'diego.design'), (SELECT id FROM public.posts WHERE content = 'Eu quase desisti do estágio na segunda semana. Achava que não era bom o suficiente. O @ricardo.alves' LIMIT 1), 'claps', (SELECT created_at FROM public.posts WHERE content = 'Eu quase desisti do estágio na segunda semana. Achava que não era bom o suficiente. O @ricardo.alves' LIMIT 1) + interval '2.6 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'marcos.vinicius'), (SELECT id FROM public.posts WHERE content = 'Eu quase desisti do estágio na segunda semana. Achava que não era bom o suficiente. O @ricardo.alves' LIMIT 1), 'loved', (SELECT created_at FROM public.posts WHERE content = 'Eu quase desisti do estágio na segunda semana. Achava que não era bom o suficiente. O @ricardo.alves' LIMIT 1) + interval '6.7 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'fernanda.lima'), (SELECT id FROM public.posts WHERE content = 'Eu quase desisti do estágio na segunda semana. Achava que não era bom o suficiente. O @ricardo.alves' LIMIT 1), 'loved', (SELECT created_at FROM public.posts WHERE content = 'Eu quase desisti do estágio na segunda semana. Achava que não era bom o suficiente. O @ricardo.alves' LIMIT 1) + interval '13.2 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'ju.rocha'), (SELECT id FROM public.posts WHERE content = 'Eu quase desisti do estágio na segunda semana. Achava que não era bom o suficiente. O @ricardo.alves' LIMIT 1), 'loved', (SELECT created_at FROM public.posts WHERE content = 'Eu quase desisti do estágio na segunda semana. Achava que não era bom o suficiente. O @ricardo.alves' LIMIT 1) + interval '23.9 hours'),
