INSERT INTO public.comments (user_id, post_id, content, created_at)
VALUES
    ((SELECT id FROM public.profiles WHERE username = 'ana.beatriz'), (SELECT id FROM public.posts WHERE content = 'O @marcos.vinicius me convidou pra correr minha primeira meia quando eu achava que 5k era meu limite' LIMIT 1), 'Esse ''a gente volta andando'' é técnica de motivação que funciona. Marcos, você é mestre.', (SELECT created_at FROM public.posts WHERE content = 'O @marcos.vinicius me convidou pra correr minha primeira meia quando eu achava que 5k era meu limite' LIMIT 1) + interval '3 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'marcos.vinicius'), (SELECT id FROM public.posts WHERE content = 'O @marcos.vinicius me convidou pra correr minha primeira meia quando eu achava que 5k era meu limite' LIMIT 1), 'Van, eu só te lembrei do que você já era capaz. O mérito foi seu nos 21km.', (SELECT created_at FROM public.posts WHERE content = 'O @marcos.vinicius me convidou pra correr minha primeira meia quando eu achava que 5k era meu limite' LIMIT 1) + interval '6 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'lucas.ferreira'), (SELECT id FROM public.posts WHERE content = 'Eu quase desisti do estágio na segunda semana. Achava que não era bom o suficiente. O @ricardo.alves' LIMIT 1), 'Eu também quase desisti na segunda semana, Thiago. Que bom que ficou.', (SELECT created_at FROM public.posts WHERE content = 'Eu quase desisti do estágio na segunda semana. Achava que não era bom o suficiente. O @ricardo.alves' LIMIT 1) + interval '4 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'ricardo.alves'), (SELECT id FROM public.posts WHERE content = 'Eu quase desisti do estágio na segunda semana. Achava que não era bom o suficiente. O @ricardo.alves' LIMIT 1), 'Curiosidade é tudo. Thiago, valeu por ter ficado.', (SELECT created_at FROM public.posts WHERE content = 'Eu quase desisti do estágio na segunda semana. Achava que não era bom o suficiente. O @ricardo.alves' LIMIT 1) + interval '7 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'jorge.ribeiro'), (SELECT id FROM public.posts WHERE content = 'Quando meu marido faleceu, eu achei que minha vida tinha acabado. A @maria.helena me ligava todo dia' LIMIT 1), 'Helena tem esse dom. Salvar gente sem fazer barulho.', (SELECT created_at FROM public.posts WHERE content = 'Quando meu marido faleceu, eu achei que minha vida tinha acabado. A @maria.helena me ligava todo dia' LIMIT 1) + interval '6 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'vanessa.martins'), (SELECT id FROM public.posts WHERE content = 'Quando meu marido faleceu, eu achei que minha vida tinha acabado. A @maria.helena me ligava todo dia' LIMIT 1), 'Que história. Dona Lúcia, obrigada por compartilhar isso aqui.', (SELECT created_at FROM public.posts WHERE content = 'Quando meu marido faleceu, eu achei que minha vida tinha acabado. A @maria.helena me ligava todo dia' LIMIT 1) + interval '14 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'edson.pereira'), (SELECT id FROM public.posts WHERE content = 'O @edson.pereira me disse em 1995: ''Antônio, trabalha com as mãos mas pensa com a cabeça.'' Eu era ca' LIMIT 1), 'Antônio, eu falei aquilo numa hora qualquer e o senhor levou pra vida. É honra.', (SELECT created_at FROM public.posts WHERE content = 'O @edson.pereira me disse em 1995: ''Antônio, trabalha com as mãos mas pensa com a cabeça.'' Eu era ca' LIMIT 1) + interval '8 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'maria.helena'), (SELECT id FROM public.posts WHERE content = 'A @maria.helena me disse uma vez: ''Jorge, aposentar o corpo não é aposentar a cabeça.'' Eu tava viran' LIMIT 1), 'Jorge, vou ser eternamente grata por você ter me ouvido naquele dia.', (SELECT created_at FROM public.posts WHERE content = 'A @maria.helena me disse uma vez: ''Jorge, aposentar o corpo não é aposentar a cabeça.'' Eu tava viran' LIMIT 1) + interval '6 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'dona.lucia'), (SELECT id FROM public.posts WHERE content = 'A @maria.helena me disse uma vez: ''Jorge, aposentar o corpo não é aposentar a cabeça.'' Eu tava viran' LIMIT 1), 'Helena salva a aposentadoria de muita gente. Inclusive a minha.', (SELECT created_at FROM public.posts WHERE content = 'A @maria.helena me disse uma vez: ''Jorge, aposentar o corpo não é aposentar a cabeça.'' Eu tava viran' LIMIT 1) + interval '14 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'patricia.nunes'), (SELECT id FROM public.posts WHERE content = 'A @dona.lucia me disse algo simples que eu nunca esqueci: ''Helena, solidão é quando a gente para de ' LIMIT 1), 'Vou anotar essa frase. ''Solidão é parar de ir atrás dos outros.'' Forte demais.', (SELECT created_at FROM public.posts WHERE content = 'A @dona.lucia me disse algo simples que eu nunca esqueci: ''Helena, solidão é quando a gente para de ' LIMIT 1) + interval '5 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'fernanda.lima'), (SELECT id FROM public.posts WHERE content = 'A @fernanda.lima deixou um post-it na minha mesa (sim, a gente ainda vai pro escritório às vezes) es' LIMIT 1), 'Rafa, eu nem lembrava desse post-it. Que bom que importou. ❤️', (SELECT created_at FROM public.posts WHERE content = 'A @fernanda.lima deixou um post-it na minha mesa (sim, a gente ainda vai pro escritório às vezes) es' LIMIT 1) + interval '4 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'ju.rocha'), (SELECT id FROM public.posts WHERE content = 'A @fernanda.lima deixou um post-it na minha mesa (sim, a gente ainda vai pro escritório às vezes) es' LIMIT 1), 'Quatro palavras mudam dia. Vou começar a deixar bilhetinhos pelo time.', (SELECT created_at FROM public.posts WHERE content = 'A @fernanda.lima deixou um post-it na minha mesa (sim, a gente ainda vai pro escritório às vezes) es' LIMIT 1) + interval '9 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'ju.rocha'), (SELECT id FROM public.posts WHERE content = 'A @ju.rocha me mandou um áudio de 12 segundos depois de uma reunião tensa: ''Cami, você mandou bem. P' LIMIT 1), 'Cami, você merecia ouvir. Tava bom mesmo. ✨', (SELECT created_at FROM public.posts WHERE content = 'A @ju.rocha me mandou um áudio de 12 segundos depois de uma reunião tensa: ''Cami, você mandou bem. P' LIMIT 1) + interval '5 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'carlos.henrique'), (SELECT id FROM public.posts WHERE content = 'O @carlos.henrique me mandou o link de uma vaga que tinha a minha cara. Nem era da empresa dele, nem' LIMIT 1), 'Pedro, você é dos melhores devs que conheço. Eu manderia 10 vagas se aparecessem.', (SELECT created_at FROM public.posts WHERE content = 'O @carlos.henrique me mandou o link de uma vaga que tinha a minha cara. Nem era da empresa dele, nem' LIMIT 1) + interval '4 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'renata.campos'), (SELECT id FROM public.posts WHERE content = 'A @renata.campos nunca me deu uma aula de liderança. Mas eu aprendo toda vez que vejo ela em reunião' LIMIT 1), 'Ana, eu não sabia que isso era visível. Obrigada. Vou tentar continuar assim.', (SELECT created_at FROM public.posts WHERE content = 'A @renata.campos nunca me deu uma aula de liderança. Mas eu aprendo toda vez que vejo ela em reunião' LIMIT 1) + interval '6 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'vanessa.martins'), (SELECT id FROM public.posts WHERE content = 'A @renata.campos nunca me deu uma aula de liderança. Mas eu aprendo toda vez que vejo ela em reunião' LIMIT 1), 'A Ana tá certa. Renata, você lidera mais pelo exemplo do que pelas reuniões.', (SELECT created_at FROM public.posts WHERE content = 'A @renata.campos nunca me deu uma aula de liderança. Mas eu aprendo toda vez que vejo ela em reunião' LIMIT 1) + interval '11 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'pedro.augusto'), (SELECT id FROM public.posts WHERE content = 'O @seu.antonio me ensinou paciência sem dizer uma palavra sobre paciência. Foi num churrasco: eu que' LIMIT 1), '''A carne avisa quando tá pronta'' = ''o código avisa quando tá pronto''. Mesma sabedoria. 🍖💻', (SELECT created_at FROM public.posts WHERE content = 'O @seu.antonio me ensinou paciência sem dizer uma palavra sobre paciência. Foi num churrasco: eu que' LIMIT 1) + interval '4 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'patricia.nunes'), (SELECT id FROM public.posts WHERE content = 'A @patricia.nunes é professora e eu sou designer, mas ela me ensinou mais sobre comunicação visual d' LIMIT 1), 'Diego, fico feliz que algo de aula de pedagogia tenha chegado em design. Você usa bem!', (SELECT created_at FROM public.posts WHERE content = 'A @patricia.nunes é professora e eu sou designer, mas ela me ensinou mais sobre comunicação visual d' LIMIT 1) + interval '5 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'ju.rocha'), (SELECT id FROM public.posts WHERE content = 'A @patricia.nunes é professora e eu sou designer, mas ela me ensinou mais sobre comunicação visual d' LIMIT 1), 'Se o usuário não entendeu, o problema é da gente. Vou colar isso no Figma.', (SELECT created_at FROM public.posts WHERE content = 'A @patricia.nunes é professora e eu sou designer, mas ela me ensinou mais sobre comunicação visual d' LIMIT 1) + interval '10 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'diego.design'), (SELECT id FROM public.posts WHERE content = 'Ontem a @ju.rocha ficou meia hora depois do expediente me ajudando a debugar um problema de CSS que ' LIMIT 1), 'Ju é fora da curva mesmo. A gente tem sorte de ter ela no time.', (SELECT created_at FROM public.posts WHERE content = 'Ontem a @ju.rocha ficou meia hora depois do expediente me ajudando a debugar um problema de CSS que ' LIMIT 1) + interval '4 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'ricardo.alves'), (SELECT id FROM public.posts WHERE content = 'Ontem a @ju.rocha ficou meia hora depois do expediente me ajudando a debugar um problema de CSS que ' LIMIT 1), 'Esse tipo de coisa não aparece em OKR mas faz a diferença real. 🙌', (SELECT created_at FROM public.posts WHERE content = 'Ontem a @ju.rocha ficou meia hora depois do expediente me ajudando a debugar um problema de CSS que ' LIMIT 1) + interval '8 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'vanessa.martins'), (SELECT id FROM public.posts WHERE content = 'O @rafael.mendes chegou hoje na daily com aquele componente pronto que todo mundo achava que ia leva' LIMIT 1), 'Documentação é amor, gente. Quem documenta cuida do próximo dev. Rafa é assim mesmo.', (SELECT created_at FROM public.posts WHERE content = 'O @rafael.mendes chegou hoje na daily com aquele componente pronto que todo mundo achava que ia leva' LIMIT 1) + interval '3 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'fernanda.lima'), (SELECT id FROM public.posts WHERE content = 'O @rafael.mendes chegou hoje na daily com aquele componente pronto que todo mundo achava que ia leva' LIMIT 1), 'Esse componente salvou minha sprint, sério. Pode falar dele em todas as retros que eu apoio.', (SELECT created_at FROM public.posts WHERE content = 'O @rafael.mendes chegou hoje na daily com aquele componente pronto que todo mundo achava que ia leva' LIMIT 1) + interval '6 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'ju.rocha'), (SELECT id FROM public.posts WHERE content = 'Minha avó mora longe e eu não consigo visitar tanto quanto queria. Mas toda vez que ligo pra @dona.l' LIMIT 1), 'Diego, isso aqui é puro afeto. Que coisa linda.', (SELECT created_at FROM public.posts WHERE content = 'Minha avó mora longe e eu não consigo visitar tanto quanto queria. Mas toda vez que ligo pra @dona.l' LIMIT 1) + interval '5 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'patricia.nunes'), (SELECT id FROM public.posts WHERE content = 'Minha avó mora longe e eu não consigo visitar tanto quanto queria. Mas toda vez que ligo pra @dona.l' LIMIT 1), 'Quem é vizinho da gente também é família. Dona Lúcia parece um tesouro.', (SELECT created_at FROM public.posts WHERE content = 'Minha avó mora longe e eu não consigo visitar tanto quanto queria. Mas toda vez que ligo pra @dona.l' LIMIT 1) + interval '14 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'lucas.ferreira'), (SELECT id FROM public.posts WHERE content = 'O @thiago.costa é estagiário há 4 meses. Hoje ele fez um code review no meu PR e encontrou um bug qu' LIMIT 1), 'Cara, eu tava morrendo de medo de apontar aquilo. Obrigado por reconhecer, chefe.', (SELECT created_at FROM public.posts WHERE content = 'O @thiago.costa é estagiário há 4 meses. Hoje ele fez um code review no meu PR e encontrou um bug qu' LIMIT 1) + interval '2 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'vanessa.martins'), (SELECT id FROM public.posts WHERE content = 'O @thiago.costa é estagiário há 4 meses. Hoje ele fez um code review no meu PR e encontrou um bug qu' LIMIT 1), 'Isso diz muito sobre a cultura que o Ricardo criou no time. Estagiário se sentir seguro pra discordar é raro.', (SELECT created_at FROM public.posts WHERE content = 'O @thiago.costa é estagiário há 4 meses. Hoje ele fez um code review no meu PR e encontrou um bug qu' LIMIT 1) + interval '5 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'renata.campos'), (SELECT id FROM public.posts WHERE content = 'A @ana.beatriz tá passando por uma fase difícil pessoalmente (com a autorização dela pra eu contar i' LIMIT 1), 'Ana, força. E Van, obrigada por cuidar do time além do trabalho.', (SELECT created_at FROM public.posts WHERE content = 'A @ana.beatriz tá passando por uma fase difícil pessoalmente (com a autorização dela pra eu contar i' LIMIT 1) + interval '4 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'marcos.vinicius'), (SELECT id FROM public.posts WHERE content = 'A @ana.beatriz tá passando por uma fase difícil pessoalmente (com a autorização dela pra eu contar i' LIMIT 1), 'Pedir ajuda é coragem. Reconhecer essa coragem é mais raro ainda. ✊', (SELECT created_at FROM public.posts WHERE content = 'A @ana.beatriz tá passando por uma fase difícil pessoalmente (com a autorização dela pra eu contar i' LIMIT 1) + interval '12 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'jorge.ribeiro'), (SELECT id FROM public.posts WHERE content = 'O Antônio, meu vizinho de tantos anos... ontem ele apareceu aqui em casa com a prateleira da cozinha' LIMIT 1), 'O Antônio é assim desde que eu me lembro. Não espera pedir.', (SELECT created_at FROM public.posts WHERE content = 'O Antônio, meu vizinho de tantos anos... ontem ele apareceu aqui em casa com a prateleira da cozinha' LIMIT 1) + interval '12 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'jorge.ribeiro'), (SELECT id FROM public.posts WHERE content = 'A Lúcia fez bolo de fubá pra mim ontem. Sem motivo. Disse que lembrou que eu gostava. Às vezes a gen' LIMIT 1), 'Bolo de fubá da Lúcia é coisa séria. Antônio, o senhor é privilegiado.', (SELECT created_at FROM public.posts WHERE content = 'A Lúcia fez bolo de fubá pra mim ontem. Sem motivo. Disse que lembrou que eu gostava. Às vezes a gen' LIMIT 1) + interval '6 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'edson.pereira'), (SELECT id FROM public.posts WHERE content = 'A Lúcia fez bolo de fubá pra mim ontem. Sem motivo. Disse que lembrou que eu gostava. Às vezes a gen' LIMIT 1), 'Casal raiz. 👏', (SELECT created_at FROM public.posts WHERE content = 'A Lúcia fez bolo de fubá pra mim ontem. Sem motivo. Disse que lembrou que eu gostava. Às vezes a gen' LIMIT 1) + interval '18 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'pedro.augusto'), (SELECT id FROM public.posts WHERE content = 'O @pedro.augusto podia ter ido embora depois do primeiro tempo (o cara tinha acordo com a esposa pra' LIMIT 1), 'Eu não sou herói, sou burro mesmo kkkk mas valeu a bronca em casa', (SELECT created_at FROM public.posts WHERE content = 'O @pedro.augusto podia ter ido embora depois do primeiro tempo (o cara tinha acordo com a esposa pra' LIMIT 1) + interval '1 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'ricardo.alves'), (SELECT id FROM public.posts WHERE content = 'O @pedro.augusto podia ter ido embora depois do primeiro tempo (o cara tinha acordo com a esposa pra' LIMIT 1), 'A esposa do Pedro, se estiver lendo: a culpa é do Carlos que marcou o jogo', (SELECT created_at FROM public.posts WHERE content = 'O @pedro.augusto podia ter ido embora depois do primeiro tempo (o cara tinha acordo com a esposa pra' LIMIT 1) + interval '2 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'rafael.mendes'), (SELECT id FROM public.posts WHERE content = 'A @camila.santos correu a primeira 10k dela hoje. Ela começou em janeiro sem conseguir fazer 1km sem' LIMIT 1), 'Cami!!!!! Que orgulho! Lembro quando você disse que odiava correr hahaha', (SELECT created_at FROM public.posts WHERE content = 'A @camila.santos correu a primeira 10k dela hoje. Ela começou em janeiro sem conseguir fazer 1km sem' LIMIT 1) + interval '3 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'ana.beatriz'), (SELECT id FROM public.posts WHERE content = 'A @camila.santos correu a primeira 10k dela hoje. Ela começou em janeiro sem conseguir fazer 1km sem' LIMIT 1), 'Chorei vendo essa foto. Sério. To muito feliz por você!', (SELECT created_at FROM public.posts WHERE content = 'A @camila.santos correu a primeira 10k dela hoje. Ela começou em janeiro sem conseguir fazer 1km sem' LIMIT 1) + interval '5 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'vanessa.martins'), (SELECT id FROM public.posts WHERE content = 'O @ricardo.alves podia ser aquele tech lead que só cobra e delega. Mas toda vez que eu travo em algo' LIMIT 1), 'Posso confirmar: o Ricardo é assim com TODO mundo. Não muda quando vira liderança.', (SELECT created_at FROM public.posts WHERE content = 'O @ricardo.alves podia ser aquele tech lead que só cobra e delega. Mas toda vez que eu travo em algo' LIMIT 1) + interval '2 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'lucas.ferreira'), (SELECT id FROM public.posts WHERE content = 'O @ricardo.alves podia ser aquele tech lead que só cobra e delega. Mas toda vez que eu travo em algo' LIMIT 1), 'Thiago tá certíssimo. O Ricardo me explicou o mesmo bug umas 4 vezes sem reclamar uma vez.', (SELECT created_at FROM public.posts WHERE content = 'O @ricardo.alves podia ser aquele tech lead que só cobra e delega. Mas toda vez que eu travo em algo' LIMIT 1) + interval '5 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'marcos.vinicius'), (SELECT id FROM public.posts WHERE content = 'Semana passada eu desabei numa call com a @vanessa.martins — chorei, contei tudo, fiz aquele papel q' LIMIT 1), 'Escutar é das coisas mais difíceis. Vanessa faz parecer fácil.', (SELECT created_at FROM public.posts WHERE content = 'Semana passada eu desabei numa call com a @vanessa.martins — chorei, contei tudo, fiz aquele papel q' LIMIT 1) + interval '6 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'ju.rocha'), (SELECT id FROM public.posts WHERE content = 'Percebi um padrão no @rafael.mendes que quero registrar: em toda retro, ele fala pelo menos uma cois' LIMIT 1), 'Comecei a notar isso depois desse post da Fer. É verdade!', (SELECT created_at FROM public.posts WHERE content = 'Percebi um padrão no @rafael.mendes que quero registrar: em toda retro, ele fala pelo menos uma cois' LIMIT 1) + interval '4 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'ana.beatriz'), (SELECT id FROM public.posts WHERE content = 'Percebi um padrão no @rafael.mendes que quero registrar: em toda retro, ele fala pelo menos uma cois' LIMIT 1), 'Vou copiar essa prática nas minhas retros também. Bora propagar.', (SELECT created_at FROM public.posts WHERE content = 'Percebi um padrão no @rafael.mendes que quero registrar: em toda retro, ele fala pelo menos uma cois' LIMIT 1) + interval '8 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'vanessa.martins'), (SELECT id FROM public.posts WHERE content = 'Conheci a @maria.helena numa roda de leitura. Ela tem 73 anos e lê mais que qualquer pessoa que eu c' LIMIT 1), 'Saber escutar é o que me falta. Maria Helena é referência.', (SELECT created_at FROM public.posts WHERE content = 'Conheci a @maria.helena numa roda de leitura. Ela tem 73 anos e lê mais que qualquer pessoa que eu c' LIMIT 1) + interval '6 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'ana.beatriz'), (SELECT id FROM public.posts WHERE content = 'O @marcos.vinicius me mandou mensagem no sábado de manhã pra saber se eu ia pro treino. Eu não ia — ' LIMIT 1), 'Isso de esperar no km3 já fizeram comigo TBM. O Marcos é bom demais.', (SELECT created_at FROM public.posts WHERE content = 'O @marcos.vinicius me mandou mensagem no sábado de manhã pra saber se eu ia pro treino. Eu não ia — ' LIMIT 1) + interval '4 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'renata.campos'), (SELECT id FROM public.posts WHERE content = 'O @marcos.vinicius me mandou mensagem no sábado de manhã pra saber se eu ia pro treino. Eu não ia — ' LIMIT 1), 'Esse é o líder que muda jornada. Cami, parabéns por não desistir.', (SELECT created_at FROM public.posts WHERE content = 'O @marcos.vinicius me mandou mensagem no sábado de manhã pra saber se eu ia pro treino. Eu não ia — ' LIMIT 1) + interval '7 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'carlos.henrique'), (SELECT id FROM public.posts WHERE content = 'Quinta passada o @carlos.henrique errou um gol feito (sim, a bola ia entrar sozinha e ele conseguiu ' LIMIT 1), 'Eu QUASE fiz o gol ok? A bola desviou. Desviou. (Não desviou, mas me deixa sonhar.)', (SELECT created_at FROM public.posts WHERE content = 'Quinta passada o @carlos.henrique errou um gol feito (sim, a bola ia entrar sozinha e ele conseguiu ' LIMIT 1) + interval '0.5 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'thiago.costa'), (SELECT id FROM public.posts WHERE content = 'Quinta passada o @carlos.henrique errou um gol feito (sim, a bola ia entrar sozinha e ele conseguiu ' LIMIT 1), 'o Carlos é assim, erra gol mas acerta amizade kkk', (SELECT created_at FROM public.posts WHERE content = 'Quinta passada o @carlos.henrique errou um gol feito (sim, a bola ia entrar sozinha e ele conseguiu ' LIMIT 1) + interval '1 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'carlos.henrique'), (SELECT id FROM public.posts WHERE content = 'O @thiago.costa e eu entramos juntos como estagiários. Tinha tudo pra ser competição. Mas quando eu ' LIMIT 1), 'Os dois juntos são monstros. Adoro ver vocês crescerem.', (SELECT created_at FROM public.posts WHERE content = 'O @thiago.costa e eu entramos juntos como estagiários. Tinha tudo pra ser competição. Mas quando eu ' LIMIT 1) + interval '3 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'ricardo.alves'), (SELECT id FROM public.posts WHERE content = 'O @thiago.costa e eu entramos juntos como estagiários. Tinha tudo pra ser competição. Mas quando eu ' LIMIT 1), 'Thiago, eu tava torcendo pra acontecer essa parceria. Continua.', (SELECT created_at FROM public.posts WHERE content = 'O @thiago.costa e eu entramos juntos como estagiários. Tinha tudo pra ser competição. Mas quando eu ' LIMIT 1) + interval '6 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'vanessa.martins'), (SELECT id FROM public.posts WHERE content = 'Preciso falar do @ricardo.alves como líder técnico. Em 6 meses trabalhando com ele, nunca vi ele pux' LIMIT 1), 'Posso confirmar: 100% verdade. O Ricardo nunca puxa crédito.', (SELECT created_at FROM public.posts WHERE content = 'Preciso falar do @ricardo.alves como líder técnico. Em 6 meses trabalhando com ele, nunca vi ele pux' LIMIT 1) + interval '2 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'rafael.mendes'), (SELECT id FROM public.posts WHERE content = 'Preciso falar do @ricardo.alves como líder técnico. Em 6 meses trabalhando com ele, nunca vi ele pux' LIMIT 1), 'Endorso 1000%. Ricardo é exemplo de como liderança deveria ser ensinada.', (SELECT created_at FROM public.posts WHERE content = 'Preciso falar do @ricardo.alves como líder técnico. Em 6 meses trabalhando com ele, nunca vi ele pux' LIMIT 1) + interval '3 hours');
