    ((SELECT id FROM public.profiles WHERE username = 'ana.beatriz'), (SELECT id FROM public.posts WHERE content = 'Preciso falar do @ricardo.alves como líder técnico. Em 6 meses trabalhando com ele, nunca vi ele pux' LIMIT 1), 'Esse ''eu não vi esse risco'' é a humildade que falta em muito gestor. 👏', (SELECT created_at FROM public.posts WHERE content = 'Preciso falar do @ricardo.alves como líder técnico. Em 6 meses trabalhando com ele, nunca vi ele pux' LIMIT 1) + interval '5 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'seu.antonio'), (SELECT id FROM public.posts WHERE content = 'Lembrei hoje do Edson me ensinando a trocar pneu em 1987. A gente mal se conhecia, eu tinha acabado ' LIMIT 1), 'Esse dia eu lembro. O Jorge era teimoso, não queria ajuda. Mas eu sou mais teimoso.', (SELECT created_at FROM public.posts WHERE content = 'Lembrei hoje do Edson me ensinando a trocar pneu em 1987. A gente mal se conhecia, eu tinha acabado ' LIMIT 1) + interval '24 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'patricia.nunes'), (SELECT id FROM public.posts WHERE content = 'A @patricia.nunes me ensinou que nunca é tarde pra aprender. Ela que é professora virou minha aluna ' LIMIT 1), 'Helena, ler isso me emocionou. A senhora me ensina muito mais do que eu ensino.', (SELECT created_at FROM public.posts WHERE content = 'A @patricia.nunes me ensinou que nunca é tarde pra aprender. Ela que é professora virou minha aluna ' LIMIT 1) + interval '3 hours'),
