    ((SELECT id FROM public.profiles WHERE username = 'rafael.mendes'), (SELECT id FROM public.posts WHERE content = 'Quero reconhecer a @fernanda.lima por algo que pouca gente viu: ela refez a dashboard de métricas 3 ' LIMIT 1), 'Refazer 3 vezes sem ninguém pedir é amor pelo ofício. 🙏', (SELECT created_at FROM public.posts WHERE content = 'Quero reconhecer a @fernanda.lima por algo que pouca gente viu: ela refez a dashboard de métricas 3 ' LIMIT 1) + interval '7 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'dona.lucia'), (SELECT id FROM public.posts WHERE content = 'O Antônio carrega 70 anos nas costas e humildade no jeito. Outro dia tava ensinando o neto a lixar m' LIMIT 1), 'Edson, você descreveu o Antônio de verdade. Ele não muda mesmo.', (SELECT created_at FROM public.posts WHERE content = 'O Antônio carrega 70 anos nas costas e humildade no jeito. Outro dia tava ensinando o neto a lixar m' LIMIT 1) + interval '6 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'jorge.ribeiro'), (SELECT id FROM public.posts WHERE content = 'O Antônio carrega 70 anos nas costas e humildade no jeito. Outro dia tava ensinando o neto a lixar m' LIMIT 1), 'Trinta anos depois, mesmas mãos, mesma paciência. Privilégio conhecer.', (SELECT created_at FROM public.posts WHERE content = 'O Antônio carrega 70 anos nas costas e humildade no jeito. Outro dia tava ensinando o neto a lixar m' LIMIT 1) + interval '9 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'ju.rocha'), (SELECT id FROM public.posts WHERE content = 'Entreguei um layout semana passada que eu achava bom. O @rafael.mendes olhou, ficou quieto uns segun' LIMIT 1), 'Esse ''e se a gente invertesse'' é técnica de feedback que vou usar a vida inteira.', (SELECT created_at FROM public.posts WHERE content = 'Entreguei um layout semana passada que eu achava bom. O @rafael.mendes olhou, ficou quieto uns segun' LIMIT 1) + interval '4 hours'),
