    ((SELECT id FROM public.profiles WHERE username = 'vanessa.martins'), (SELECT id FROM public.posts WHERE content = 'A @renata.campos correu a maratona de São Paulo domingo. 42km. Sabe o que ela fez na segunda? Chegou' LIMIT 1), 'Renata é a prova viva de que disciplina não exclui prazer. Aprendi muito vendo ela.', (SELECT created_at FROM public.posts WHERE content = 'A @renata.campos correu a maratona de São Paulo domingo. 42km. Sabe o que ela fez na segunda? Chegou' LIMIT 1) + interval '9 hours'),
