    ((SELECT id FROM public.profiles WHERE username = 'thiago.costa'), (SELECT id FROM public.posts WHERE content = 'O @diego.design não é o melhor jogador da pelada (desculpa, Diego). Mas é o cara que todo mundo quer' LIMIT 1), 'Diego é o MVP emocional da pelada, oficialmente.', (SELECT created_at FROM public.posts WHERE content = 'O @diego.design não é o melhor jogador da pelada (desculpa, Diego). Mas é o cara que todo mundo quer' LIMIT 1) + interval '11 hours'),
