    ((SELECT id FROM public.profiles WHERE username = 'ana.beatriz'), (SELECT id FROM public.posts WHERE content = 'O @rafael.mendes completou 100 dias seguidos de treino hoje. Cem. Chuva, sol, viagem, criança doente' LIMIT 1), 'Esses 15 minutos de esteira no hotel são os que mais valem. Disciplina é nos dias difíceis.', (SELECT created_at FROM public.posts WHERE content = 'O @rafael.mendes completou 100 dias seguidos de treino hoje. Cem. Chuva, sol, viagem, criança doente' LIMIT 1) + interval '5 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'renata.campos'), (SELECT id FROM public.posts WHERE content = 'O @rafael.mendes completou 100 dias seguidos de treino hoje. Cem. Chuva, sol, viagem, criança doente' LIMIT 1), 'Inspirador demais. 🏃‍♂️', (SELECT created_at FROM public.posts WHERE content = 'O @rafael.mendes completou 100 dias seguidos de treino hoje. Cem. Chuva, sol, viagem, criança doente' LIMIT 1) + interval '7 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'carlos.henrique'), (SELECT id FROM public.posts WHERE content = 'O @lucas.ferreira tava travado num bug há 2 dias e com vergonha de pedir ajuda. Eu percebi porque el' LIMIT 1), 'Thiago, isso é maturidade. Notar que alguém tá quieto demais é radar de bom amigo.', (SELECT created_at FROM public.posts WHERE content = 'O @lucas.ferreira tava travado num bug há 2 dias e com vergonha de pedir ajuda. Eu percebi porque el' LIMIT 1) + interval '4 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'ricardo.alves'), (SELECT id FROM public.posts WHERE content = 'O @lucas.ferreira tava travado num bug há 2 dias e com vergonha de pedir ajuda. Eu percebi porque el' LIMIT 1), 'Esse tipo de coisa não cabe em PR review mas é o que segura o time.', (SELECT created_at FROM public.posts WHERE content = 'O @lucas.ferreira tava travado num bug há 2 dias e com vergonha de pedir ajuda. Eu percebi porque el' LIMIT 1) + interval '7 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'rafael.mendes'), (SELECT id FROM public.posts WHERE content = 'Situação real: eu errei feio num alinhamento com stakeholder. Tipo, errei de verdade. O @ricardo.alv' LIMIT 1), 'Esse ''a gente conserta junto'' deveria ser regra de gestão.', (SELECT created_at FROM public.posts WHERE content = 'Situação real: eu errei feio num alinhamento com stakeholder. Tipo, errei de verdade. O @ricardo.alv' LIMIT 1) + interval '4 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'fernanda.lima'), (SELECT id FROM public.posts WHERE content = 'Situação real: eu errei feio num alinhamento com stakeholder. Tipo, errei de verdade. O @ricardo.alv' LIMIT 1), 'Ricardo é referência. Vanessa também, por reconhecer isso publicamente. 💪', (SELECT created_at FROM public.posts WHERE content = 'Situação real: eu errei feio num alinhamento com stakeholder. Tipo, errei de verdade. O @ricardo.alv' LIMIT 1) + interval '8 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'ju.rocha'), (SELECT id FROM public.posts WHERE content = 'Faço uma observação sobre a @vanessa.martins — ela é a pessoa que mais lembra de aniversários, datas' LIMIT 1), 'Van é puro cuidado. Lembrar do café coado da Fer é o tipo de detalhe que cria família.', (SELECT created_at FROM public.posts WHERE content = 'Faço uma observação sobre a @vanessa.martins — ela é a pessoa que mais lembra de aniversários, datas' LIMIT 1) + interval '3 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'ricardo.alves'), (SELECT id FROM public.posts WHERE content = 'Faço uma observação sobre a @vanessa.martins — ela é a pessoa que mais lembra de aniversários, datas' LIMIT 1), 'Van, você é o tecido conjuntivo desse time. Sério.', (SELECT created_at FROM public.posts WHERE content = 'Faço uma observação sobre a @vanessa.martins — ela é a pessoa que mais lembra de aniversários, datas' LIMIT 1) + interval '6 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'rafael.mendes'), (SELECT id FROM public.posts WHERE content = 'Obrigada @ju.rocha por ter sido honesta comigo sobre a apresentação. Eu queria ouvir ''tá ótimo'' e vo' LIMIT 1), 'Ju dá o melhor feedback do mundo. Honesto sem ser duro.', (SELECT created_at FROM public.posts WHERE content = 'Obrigada @ju.rocha por ter sido honesta comigo sobre a apresentação. Eu queria ouvir ''tá ótimo'' e vo' LIMIT 1) + interval '5 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'lucas.ferreira'), (SELECT id FROM public.posts WHERE content = 'O @thiago.costa tem 21 anos e já entende algo que muita gente de 40 não entende: que time é mais imp' LIMIT 1), 'Cara, eu nem sei o que dizer. Obrigado Thiago. De verdade.', (SELECT created_at FROM public.posts WHERE content = 'O @thiago.costa tem 21 anos e já entende algo que muita gente de 40 não entende: que time é mais imp' LIMIT 1) + interval '3 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'ricardo.alves'), (SELECT id FROM public.posts WHERE content = 'O @thiago.costa tem 21 anos e já entende algo que muita gente de 40 não entende: que time é mais imp' LIMIT 1), 'Esse moleque vai longe mesmo. Time é maior que ego, e o Thiago entendeu cedo.', (SELECT created_at FROM public.posts WHERE content = 'O @thiago.costa tem 21 anos e já entende algo que muita gente de 40 não entende: que time é mais imp' LIMIT 1) + interval '4 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'lucas.ferreira'), (SELECT id FROM public.posts WHERE content = 'O @thiago.costa tem 21 anos e já entende algo que muita gente de 40 não entende: que time é mais imp' LIMIT 1), 'Eu lembro daquele jogo. Quando o Thiago começou a passar pra mim eu pensei: ''tá com pena ou tá vendo''. Era ver.', (SELECT created_at FROM public.posts WHERE content = 'O @thiago.costa tem 21 anos e já entende algo que muita gente de 40 não entende: que time é mais imp' LIMIT 1) + interval '6 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'diego.design'), (SELECT id FROM public.posts WHERE content = 'O @thiago.costa tem 21 anos e já entende algo que muita gente de 40 não entende: que time é mais imp' LIMIT 1), 'Aí sim. 🔥', (SELECT created_at FROM public.posts WHERE content = 'O @thiago.costa tem 21 anos e já entende algo que muita gente de 40 não entende: que time é mais imp' LIMIT 1) + interval '12 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'dona.lucia'), (SELECT id FROM public.posts WHERE content = 'Eu e a @dona.lucia nos conhecemos em 1985, numa fila de banco. Ela tava com um bebê no colo e eu aju' LIMIT 1), 'Minha querida Helena, não sabia que a senhora ia me fazer chorar logo cedo assim', (SELECT created_at FROM public.posts WHERE content = 'Eu e a @dona.lucia nos conhecemos em 1985, numa fila de banco. Ela tava com um bebê no colo e eu aju' LIMIT 1) + interval '4 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'vanessa.martins'), (SELECT id FROM public.posts WHERE content = 'Eu e a @dona.lucia nos conhecemos em 1985, numa fila de banco. Ela tava com um bebê no colo e eu aju' LIMIT 1), 'Que história linda. 40 anos de café juntas. ❤️', (SELECT created_at FROM public.posts WHERE content = 'Eu e a @dona.lucia nos conhecemos em 1985, numa fila de banco. Ela tava com um bebê no colo e eu aju' LIMIT 1) + interval '6 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'patricia.nunes'), (SELECT id FROM public.posts WHERE content = 'Eu e a @dona.lucia nos conhecemos em 1985, numa fila de banco. Ela tava com um bebê no colo e eu aju' LIMIT 1), 'Isso aqui é literatura. Helena, você escreve com o coração.', (SELECT created_at FROM public.posts WHERE content = 'Eu e a @dona.lucia nos conhecemos em 1985, numa fila de banco. Ela tava com um bebê no colo e eu aju' LIMIT 1) + interval '10 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'thiago.costa'), (SELECT id FROM public.posts WHERE content = 'Uma coisa sobre o @ricardo.alves que ninguém fala: ele responde mensagem de todo mundo. Estagiário, ' LIMIT 1), 'Posso confirmar que ele responde estagiário sim. Isso me marcou no primeiro mês.', (SELECT created_at FROM public.posts WHERE content = 'Uma coisa sobre o @ricardo.alves que ninguém fala: ele responde mensagem de todo mundo. Estagiário, ' LIMIT 1) + interval '4 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'ana.beatriz'), (SELECT id FROM public.posts WHERE content = 'Uma coisa sobre o @ricardo.alves que ninguém fala: ele responde mensagem de todo mundo. Estagiário, ' LIMIT 1), 'Acessibilidade é forma de respeito. Ricardo tem isso.', (SELECT created_at FROM public.posts WHERE content = 'Uma coisa sobre o @ricardo.alves que ninguém fala: ele responde mensagem de todo mundo. Estagiário, ' LIMIT 1) + interval '8 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'marcos.vinicius'), (SELECT id FROM public.posts WHERE content = 'Quero celebrar a @ana.beatriz — ela começou a correr há 5 meses, como mãe solo, encaixando treino na' LIMIT 1), 'Ana, foi lindo ver você cruzar. O Miguel deve ter ficado orgulhosíssimo.', (SELECT created_at FROM public.posts WHERE content = 'Quero celebrar a @ana.beatriz — ela começou a correr há 5 meses, como mãe solo, encaixando treino na' LIMIT 1) + interval '3 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'ana.beatriz'), (SELECT id FROM public.posts WHERE content = 'Quero celebrar a @ana.beatriz — ela começou a correr há 5 meses, como mãe solo, encaixando treino na' LIMIT 1), 'Vocês vão me fazer chorar de novo. O Miguel ficou todo orgulhoso quando contei pra ele.', (SELECT created_at FROM public.posts WHERE content = 'Quero celebrar a @ana.beatriz — ela começou a correr há 5 meses, como mãe solo, encaixando treino na' LIMIT 1) + interval '6 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'vanessa.martins'), (SELECT id FROM public.posts WHERE content = 'Quero celebrar a @ana.beatriz — ela começou a correr há 5 meses, como mãe solo, encaixando treino na' LIMIT 1), 'Mãe solo correndo meia maratona é sobrenatural. 👏', (SELECT created_at FROM public.posts WHERE content = 'Quero celebrar a @ana.beatriz — ela começou a correr há 5 meses, como mãe solo, encaixando treino na' LIMIT 1) + interval '8 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'camila.santos'), (SELECT id FROM public.posts WHERE content = 'Quero celebrar a @ana.beatriz — ela começou a correr há 5 meses, como mãe solo, encaixando treino na' LIMIT 1), 'Você inspirou metade do grupo de corrida, Ana. Sério.', (SELECT created_at FROM public.posts WHERE content = 'Quero celebrar a @ana.beatriz — ela começou a correr há 5 meses, como mãe solo, encaixando treino na' LIMIT 1) + interval '14 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'thiago.costa'), (SELECT id FROM public.posts WHERE content = 'O @carlos.henrique me explicou git rebase umas 5 vezes. Cinco. Na quinta vez eu entendi (mais ou men' LIMIT 1), 'Git rebase é troll mesmo. Carlos teve paciência de santo.', (SELECT created_at FROM public.posts WHERE content = 'O @carlos.henrique me explicou git rebase umas 5 vezes. Cinco. Na quinta vez eu entendi (mais ou men' LIMIT 1) + interval '3 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'ricardo.alves'), (SELECT id FROM public.posts WHERE content = 'O @carlos.henrique me explicou git rebase umas 5 vezes. Cinco. Na quinta vez eu entendi (mais ou men' LIMIT 1), 'Tratar ignorância com respeito é virtude rara. Carlos manda bem.', (SELECT created_at FROM public.posts WHERE content = 'O @carlos.henrique me explicou git rebase umas 5 vezes. Cinco. Na quinta vez eu entendi (mais ou men' LIMIT 1) + interval '6 hours'),
