    ((SELECT id FROM public.profiles WHERE username = 'rafael.mendes'), (SELECT id FROM public.posts WHERE content = 'O @diego.design recebeu um feedback duro sobre um layout na semana passada. Em vez de ficar na defen' LIMIT 1), 'Maturidade é isso mesmo. Diego, parabéns. 🎯', (SELECT created_at FROM public.posts WHERE content = 'O @diego.design recebeu um feedback duro sobre um layout na semana passada. Em vez de ficar na defen' LIMIT 1) + interval '7 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'ricardo.alves'), (SELECT id FROM public.posts WHERE content = 'A @vanessa.martins percebeu que eu não tava bem antes de eu mesmo perceber. Me mandou mensagem: ''Que' LIMIT 1), 'Van tem esse radar. Percebe antes de qualquer um.', (SELECT created_at FROM public.posts WHERE content = 'A @vanessa.martins percebeu que eu não tava bem antes de eu mesmo perceber. Me mandou mensagem: ''Que' LIMIT 1) + interval '5 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'ana.beatriz'), (SELECT id FROM public.posts WHERE content = 'Eu tenho 47 anos e achava que era tarde demais pra começar a correr. Aí vi a @ana.beatriz — mãe solo' LIMIT 1), 'Patrícia, você vai amar correr. E vai chorar na primeira 5k, te aviso.', (SELECT created_at FROM public.posts WHERE content = 'Eu tenho 47 anos e achava que era tarde demais pra começar a correr. Aí vi a @ana.beatriz — mãe solo' LIMIT 1) + interval '3 hours');
