    ((SELECT id FROM public.profiles WHERE username = 'renata.campos'), (SELECT id FROM public.posts WHERE content = 'No treino de sábado a @ana.beatriz tava claramente num dia ruim. Mais lenta, sem energia, quase chor' LIMIT 1), 'Cami, você tem o instinto certo. Silêncio solidário é raro e poderoso.', (SELECT created_at FROM public.posts WHERE content = 'No treino de sábado a @ana.beatriz tava claramente num dia ruim. Mais lenta, sem energia, quase chor' LIMIT 1) + interval '5 hours'),
