    ((SELECT id FROM public.profiles WHERE username = 'edson.pereira'), (SELECT id FROM public.posts WHERE content = 'O @edson.pereira me contou que jogava no campinho do bairro dele quando era moleque — descalço, bola' LIMIT 1), 'Descalço mesmo, e a bola era de meia com jornal dentro kkk. Mas o amor pela bola era de verdade.', (SELECT created_at FROM public.posts WHERE content = 'O @edson.pereira me contou que jogava no campinho do bairro dele quando era moleque — descalço, bola' LIMIT 1) + interval '1 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'carlos.henrique'), (SELECT id FROM public.posts WHERE content = 'O @edson.pereira me contou que jogava no campinho do bairro dele quando era moleque — descalço, bola' LIMIT 1), 'Aquele gol foi obra de arte. 62 anos? Senhor Edson, o senhor é fenômeno.', (SELECT created_at FROM public.posts WHERE content = 'O @edson.pereira me contou que jogava no campinho do bairro dele quando era moleque — descalço, bola' LIMIT 1) + interval '3 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'thiago.costa'), (SELECT id FROM public.posts WHERE content = 'O @edson.pereira me contou que jogava no campinho do bairro dele quando era moleque — descalço, bola' LIMIT 1), 'Câmera lenta literal. Eu tava lá e ainda não acredito.', (SELECT created_at FROM public.posts WHERE content = 'O @edson.pereira me contou que jogava no campinho do bairro dele quando era moleque — descalço, bola' LIMIT 1) + interval '6 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'lucas.ferreira'), (SELECT id FROM public.posts WHERE content = 'O @edson.pereira me contou que jogava no campinho do bairro dele quando era moleque — descalço, bola' LIMIT 1), 'Quero jogar bola assim aos 62. 🐐', (SELECT created_at FROM public.posts WHERE content = 'O @edson.pereira me contou que jogava no campinho do bairro dele quando era moleque — descalço, bola' LIMIT 1) + interval '10 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'ana.beatriz'), (SELECT id FROM public.posts WHERE content = 'Obrigada @marcos.vinicius por ter me esperado no km 38 da maratona quando minhas pernas travaram. Vo' LIMIT 1), '''Eu sei que se vira, mas eu fico'' é a frase que eu queria ter ouvido a vida inteira.', (SELECT created_at FROM public.posts WHERE content = 'Obrigada @marcos.vinicius por ter me esperado no km 38 da maratona quando minhas pernas travaram. Vo' LIMIT 1) + interval '5 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'vanessa.martins'), (SELECT id FROM public.posts WHERE content = 'Obrigada @marcos.vinicius por ter me esperado no km 38 da maratona quando minhas pernas travaram. Vo' LIMIT 1), 'Choro toda vez que penso em 38km. Vocês dois são guerreiros.', (SELECT created_at FROM public.posts WHERE content = 'Obrigada @marcos.vinicius por ter me esperado no km 38 da maratona quando minhas pernas travaram. Vo' LIMIT 1) + interval '9 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'ricardo.alves'), (SELECT id FROM public.posts WHERE content = 'A @camila.santos encontrou um bug em produção sexta às 17h. Todo mundo tava já saindo. Ela não só re' LIMIT 1), 'QA com senso de dono é o que eleva o produto inteiro. Cami, parabéns.', (SELECT created_at FROM public.posts WHERE content = 'A @camila.santos encontrou um bug em produção sexta às 17h. Todo mundo tava já saindo. Ela não só re' LIMIT 1) + interval '3 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'ju.rocha'), (SELECT id FROM public.posts WHERE content = 'A @camila.santos encontrou um bug em produção sexta às 17h. Todo mundo tava já saindo. Ela não só re' LIMIT 1), 'Sexta às 17h e ela não fugiu? Cami, que disciplina.', (SELECT created_at FROM public.posts WHERE content = 'A @camila.santos encontrou um bug em produção sexta às 17h. Todo mundo tava já saindo. Ela não só re' LIMIT 1) + interval '7 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'dona.lucia'), (SELECT id FROM public.posts WHERE content = 'O @edson.pereira me levou no médico segunda-feira. Eu podia ter ido de ônibus, mas ele fez questão. ' LIMIT 1), 'Esses dois são família escolhida. Quanta sorte ter um amigo assim.', (SELECT created_at FROM public.posts WHERE content = 'O @edson.pereira me levou no médico segunda-feira. Eu podia ter ido de ônibus, mas ele fez questão. ' LIMIT 1) + interval '4 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'jorge.ribeiro'), (SELECT id FROM public.posts WHERE content = 'O @edson.pereira me levou no médico segunda-feira. Eu podia ter ido de ônibus, mas ele fez questão. ' LIMIT 1), 'Café no caminho de volta é a melhor parte. 👴☕', (SELECT created_at FROM public.posts WHERE content = 'O @edson.pereira me levou no médico segunda-feira. Eu podia ter ido de ônibus, mas ele fez questão. ' LIMIT 1) + interval '8 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'lucas.ferreira'), (SELECT id FROM public.posts WHERE content = 'O @lucas.ferreira fez o primeiro deploy dele em produção hoje. Sozinho. Sem ninguém segurando a mão.' LIMIT 1), 'Caramba, tô emocionado. Obrigado Carlos. E obrigado por ter tido paciência comigo quando eu não sabia nada.', (SELECT created_at FROM public.posts WHERE content = 'O @lucas.ferreira fez o primeiro deploy dele em produção hoje. Sozinho. Sem ninguém segurando a mão.' LIMIT 1) + interval '1 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'ricardo.alves'), (SELECT id FROM public.posts WHERE content = 'O @lucas.ferreira fez o primeiro deploy dele em produção hoje. Sozinho. Sem ninguém segurando a mão.' LIMIT 1), 'Esse é o ciclo bonito: a gente ensina, e um dia não precisa mais ensinar. Parabéns Lucas!', (SELECT created_at FROM public.posts WHERE content = 'O @lucas.ferreira fez o primeiro deploy dele em produção hoje. Sozinho. Sem ninguém segurando a mão.' LIMIT 1) + interval '3 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'ricardo.alves'), (SELECT id FROM public.posts WHERE content = 'O @lucas.ferreira fez o primeiro deploy dele em produção hoje. Sozinho. Sem ninguém segurando a mão.' LIMIT 1), 'Esse ''virar desnecessário'' é a melhor definição de mentor que já li. Carlos, mandou bem.', (SELECT created_at FROM public.posts WHERE content = 'O @lucas.ferreira fez o primeiro deploy dele em produção hoje. Sozinho. Sem ninguém segurando a mão.' LIMIT 1) + interval '4 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'thiago.costa'), (SELECT id FROM public.posts WHERE content = 'O @lucas.ferreira fez o primeiro deploy dele em produção hoje. Sozinho. Sem ninguém segurando a mão.' LIMIT 1), 'Lucas, parabéns!! Em breve a gente também tá ali.', (SELECT created_at FROM public.posts WHERE content = 'O @lucas.ferreira fez o primeiro deploy dele em produção hoje. Sozinho. Sem ninguém segurando a mão.' LIMIT 1) + interval '8 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'vanessa.martins'), (SELECT id FROM public.posts WHERE content = 'O @lucas.ferreira fez o primeiro deploy dele em produção hoje. Sozinho. Sem ninguém segurando a mão.' LIMIT 1), 'Esse momento merece ser eternizado. Que orgulho do time.', (SELECT created_at FROM public.posts WHERE content = 'O @lucas.ferreira fez o primeiro deploy dele em produção hoje. Sozinho. Sem ninguém segurando a mão.' LIMIT 1) + interval '12 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'jorge.ribeiro'), (SELECT id FROM public.posts WHERE content = 'Eu e o @jorge.ribeiro fomos vizinhos por 25 anos antes dele se mudar pra Santos. Sabe o que eu mais ' LIMIT 1), 'Lúcia, eu não sabia disso. Vou começar a buzinar de novo só pra senhora ouvir. 😂', (SELECT created_at FROM public.posts WHERE content = 'Eu e o @jorge.ribeiro fomos vizinhos por 25 anos antes dele se mudar pra Santos. Sabe o que eu mais ' LIMIT 1) + interval '6 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'maria.helena'), (SELECT id FROM public.posts WHERE content = 'Eu e o @jorge.ribeiro fomos vizinhos por 25 anos antes dele se mudar pra Santos. Sabe o que eu mais ' LIMIT 1), 'A Lúcia tem o dom de ver poesia no cotidiano. ❤️', (SELECT created_at FROM public.posts WHERE content = 'Eu e o @jorge.ribeiro fomos vizinhos por 25 anos antes dele se mudar pra Santos. Sabe o que eu mais ' LIMIT 1) + interval '11 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'rafael.mendes'), (SELECT id FROM public.posts WHERE content = 'A @camila.santos fez uma coisa que ninguém mais faz: ela testou meu protótipo como usuária real, não' LIMIT 1), '''Aqui eu fiquei confusa, aqui eu sorri, aqui eu desisti'' — gold standard de feedback de UX.', (SELECT created_at FROM public.posts WHERE content = 'A @camila.santos fez uma coisa que ninguém mais faz: ela testou meu protótipo como usuária real, não' LIMIT 1) + interval '5 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'fernanda.lima'), (SELECT id FROM public.posts WHERE content = 'A @camila.santos fez uma coisa que ninguém mais faz: ela testou meu protótipo como usuária real, não' LIMIT 1), 'Vou pedir pra Cami testar tudo que eu fizer daqui pra frente.', (SELECT created_at FROM public.posts WHERE content = 'A @camila.santos fez uma coisa que ninguém mais faz: ela testou meu protótipo como usuária real, não' LIMIT 1) + interval '9 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'patricia.nunes'), (SELECT id FROM public.posts WHERE content = 'Conheci a @patricia.nunes numa corrida e descobri que ela é professora de história. A gente começou ' LIMIT 1), 'Van, foi uma das melhores conversas que tive em meses. Bora repetir.', (SELECT created_at FROM public.posts WHERE content = 'Conheci a @patricia.nunes numa corrida e descobri que ela é professora de história. A gente começou ' LIMIT 1) + interval '4 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'rafael.mendes'), (SELECT id FROM public.posts WHERE content = 'A @vanessa.martins discordou de mim numa reunião. Na frente de todo mundo. Com argumentos. E tava ce' LIMIT 1), 'Discordar com argumento e dado, sem ego. Os dois acertaram aí. 👏', (SELECT created_at FROM public.posts WHERE content = 'A @vanessa.martins discordou de mim numa reunião. Na frente de todo mundo. Com argumentos. E tava ce' LIMIT 1) + interval '5 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'renata.campos'), (SELECT id FROM public.posts WHERE content = 'A @vanessa.martins discordou de mim numa reunião. Na frente de todo mundo. Com argumentos. E tava ce' LIMIT 1), 'Esse tipo de cultura precisa ser celebrado. Bom demais.', (SELECT created_at FROM public.posts WHERE content = 'A @vanessa.martins discordou de mim numa reunião. Na frente de todo mundo. Com argumentos. E tava ce' LIMIT 1) + interval '9 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'dona.lucia'), (SELECT id FROM public.posts WHERE content = 'O @jorge.ribeiro consertou o portão da minha casa semana passada. Tem 76 anos e veio com a caixa de ' LIMIT 1), 'O Jorge é assim mesmo. Caixa de ferramentas e coração grande.', (SELECT created_at FROM public.posts WHERE content = 'O @jorge.ribeiro consertou o portão da minha casa semana passada. Tem 76 anos e veio com a caixa de ' LIMIT 1) + interval '5 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'patricia.nunes'), (SELECT id FROM public.posts WHERE content = 'O @jorge.ribeiro consertou o portão da minha casa semana passada. Tem 76 anos e veio com a caixa de ' LIMIT 1), '''Me paga com um café''. Que homem. ☕', (SELECT created_at FROM public.posts WHERE content = 'O @jorge.ribeiro consertou o portão da minha casa semana passada. Tem 76 anos e veio com a caixa de ' LIMIT 1) + interval '10 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'ana.beatriz'), (SELECT id FROM public.posts WHERE content = 'A @renata.campos fez uma coisa na retro que eu nunca tinha visto uma gestora fazer: ela admitiu que ' LIMIT 1), 'Admitir erro publicamente é o ato de liderança mais subestimado que existe. Renata é exemplo.', (SELECT created_at FROM public.posts WHERE content = 'A @renata.campos fez uma coisa na retro que eu nunca tinha visto uma gestora fazer: ela admitiu que ' LIMIT 1) + interval '4 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'ricardo.alves'), (SELECT id FROM public.posts WHERE content = 'A @renata.campos fez uma coisa na retro que eu nunca tinha visto uma gestora fazer: ela admitiu que ' LIMIT 1), 'Pelo contrário mesmo. Eu sai daquela retro com mais respeito por ela.', (SELECT created_at FROM public.posts WHERE content = 'A @renata.campos fez uma coisa na retro que eu nunca tinha visto uma gestora fazer: ela admitiu que ' LIMIT 1) + interval '8 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'marcos.vinicius'), (SELECT id FROM public.posts WHERE content = 'Preciso agradecer a @camila.santos por ter corrido do meu lado sábado quando eu tava num dia péssimo' LIMIT 1), 'Vocês duas são prova de que companheirismo no esporte muda vidas.', (SELECT created_at FROM public.posts WHERE content = 'Preciso agradecer a @camila.santos por ter corrido do meu lado sábado quando eu tava num dia péssimo' LIMIT 1) + interval '6 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'renata.campos'), (SELECT id FROM public.posts WHERE content = 'Preciso agradecer a @camila.santos por ter corrido do meu lado sábado quando eu tava num dia péssimo' LIMIT 1), 'Silêncio solidário é a melhor invenção. ❤️', (SELECT created_at FROM public.posts WHERE content = 'Preciso agradecer a @camila.santos por ter corrido do meu lado sábado quando eu tava num dia péssimo' LIMIT 1) + interval '10 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'thiago.costa'), (SELECT id FROM public.posts WHERE content = 'O @ricardo.alves me disse uma frase outro dia que eu colei no monitor: ''Você não precisa saber tudo,' LIMIT 1), 'Ele continua perguntando no Stack Overflow??? KKKKKK Ricardo, gosto cada vez mais.', (SELECT created_at FROM public.posts WHERE content = 'O @ricardo.alves me disse uma frase outro dia que eu colei no monitor: ''Você não precisa saber tudo,' LIMIT 1) + interval '3 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'carlos.henrique'), (SELECT id FROM public.posts WHERE content = 'O @ricardo.alves me disse uma frase outro dia que eu colei no monitor: ''Você não precisa saber tudo,' LIMIT 1), '''Saber perguntar'' é a habilidade mais subestimada de dev sênior. Anote, juniores.', (SELECT created_at FROM public.posts WHERE content = 'O @ricardo.alves me disse uma frase outro dia que eu colei no monitor: ''Você não precisa saber tudo,' LIMIT 1) + interval '6 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'dona.lucia'), (SELECT id FROM public.posts WHERE content = 'A @dona.lucia manda foto de bolo pra mim toda semana. Não é pra me fazer inveja — é pra eu sentir qu' LIMIT 1), 'Jorge, você sempre vai ser do bairro, não importa onde more. Beijo.', (SELECT created_at FROM public.posts WHERE content = 'A @dona.lucia manda foto de bolo pra mim toda semana. Não é pra me fazer inveja — é pra eu sentir qu' LIMIT 1) + interval '4 hours');
