    ((SELECT id FROM public.profiles WHERE username = 'seu.antonio'), (SELECT id FROM public.posts WHERE content = 'Uma vez o @seu.antonio me ensinou a afiar faca com pedra. Eu, um DevOps que não sabe pregar prego, a' LIMIT 1), 'Pedro, qualquer dia desses traz a faca de novo. Tá ficando boa, falta um pouco mais.', (SELECT created_at FROM public.posts WHERE content = 'Uma vez o @seu.antonio me ensinou a afiar faca com pedra. Eu, um DevOps que não sabe pregar prego, a' LIMIT 1) + interval '18 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'ricardo.alves'), (SELECT id FROM public.posts WHERE content = 'Quero reconhecer algo que a @fernanda.lima fez discretamente: ela montou um doc com todos os process' LIMIT 1), 'Documentação invisível é a mais valiosa. Fer, mandou bem demais.', (SELECT created_at FROM public.posts WHERE content = 'Quero reconhecer algo que a @fernanda.lima fez discretamente: ela montou um doc com todos os process' LIMIT 1) + interval '4 hours'),
