INSERT INTO public.feedbacks (mentioned_user_id, author_id, post_id, content, created_at)
VALUES
    ((SELECT id FROM public.profiles WHERE username = 'maria.helena'), (SELECT id FROM public.profiles WHERE username = 'jorge.ribeiro'), (SELECT id FROM public.posts WHERE content = 'A @maria.helena me disse uma vez: ''Jorge, aposentar o corpo não é aposentar a cabeça.'' Eu tava viran' LIMIT 1), 'Jorge, eu tava com medo de te perder pra aposentadoria. Você voltou pra vida. Obrigada por ter ouvido.', (SELECT created_at FROM public.posts WHERE content = 'A @maria.helena me disse uma vez: ''Jorge, aposentar o corpo não é aposentar a cabeça.'' Eu tava viran' LIMIT 1) + interval '8 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'renata.campos'), (SELECT id FROM public.profiles WHERE username = 'ana.beatriz'), (SELECT id FROM public.posts WHERE content = 'A @renata.campos nunca me deu uma aula de liderança. Mas eu aprendo toda vez que vejo ela em reunião' LIMIT 1), 'Ana, copia mesmo. Eu copio gente que admiro. É como a liderança se propaga. Obrigada por ser observadora.', (SELECT created_at FROM public.posts WHERE content = 'A @renata.campos nunca me deu uma aula de liderança. Mas eu aprendo toda vez que vejo ela em reunião' LIMIT 1) + interval '14 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'seu.antonio'), (SELECT id FROM public.profiles WHERE username = 'lucas.ferreira'), (SELECT id FROM public.posts WHERE content = 'O @seu.antonio me ensinou paciência sem dizer uma palavra sobre paciência. Foi num churrasco: eu que' LIMIT 1), 'Lucas, paciência com madeira é a mesma com a vida. Ainda bem que serviu pro código. Espera. Funciona.', (SELECT created_at FROM public.posts WHERE content = 'O @seu.antonio me ensinou paciência sem dizer uma palavra sobre paciência. Foi num churrasco: eu que' LIMIT 1) + interval '10 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'ju.rocha'), (SELECT id FROM public.profiles WHERE username = 'rafael.mendes'), (SELECT id FROM public.posts WHERE content = 'Ontem a @ju.rocha ficou meia hora depois do expediente me ajudando a debugar um problema de CSS que ' LIMIT 1), 'Rafa, a gente é time. Não precisa agradecer. Mas... obrigada por notar. Isso importa mais do que o CSS.', (SELECT created_at FROM public.posts WHERE content = 'Ontem a @ju.rocha ficou meia hora depois do expediente me ajudando a debugar um problema de CSS que ' LIMIT 1) + interval '3 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'rafael.mendes'), (SELECT id FROM public.profiles WHERE username = 'ju.rocha'), (SELECT id FROM public.posts WHERE content = 'O @rafael.mendes chegou hoje na daily com aquele componente pronto que todo mundo achava que ia leva' LIMIT 1), 'Ju, fico envergonhado com tanta coisa boa. Mas obrigado. Documentar é só não querer que ninguém sofra o que eu sofri. 😅', (SELECT created_at FROM public.posts WHERE content = 'O @rafael.mendes chegou hoje na daily com aquele componente pronto que todo mundo achava que ia leva' LIMIT 1) + interval '5 hours'),
