    ((SELECT id FROM public.profiles WHERE username = 'carlos.henrique'), (SELECT id FROM public.profiles WHERE username = 'ricardo.alves'), (SELECT id FROM public.posts WHERE content = 'O @carlos.henrique organiza a pelada toda quinta: reserva o campo, confirma quem vai, equilibra os t' LIMIT 1), 'Ricardo, organizo porque amo ver vocês. Não é favor. É privilégio. E a bola extra é porque a primeira sempre sai.', (SELECT created_at FROM public.posts WHERE content = 'O @carlos.henrique organiza a pelada toda quinta: reserva o campo, confirma quem vai, equilibra os t' LIMIT 1) + interval '6 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'renata.campos'), (SELECT id FROM public.profiles WHERE username = 'ana.beatriz'), (SELECT id FROM public.posts WHERE content = 'A @renata.campos fez uma coisa que me marcou: no 1:1 dela comigo, em vez de falar de entrega, pergun' LIMIT 1), 'Ana, o silêncio depois do ''tô bem'' eu aprendi com terapia, não com livro de gestão. 😅 Mas funciona.', (SELECT created_at FROM public.posts WHERE content = 'A @renata.campos fez uma coisa que me marcou: no 1:1 dela comigo, em vez de falar de entrega, pergun' LIMIT 1) + interval '6 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'patricia.nunes'), (SELECT id FROM public.profiles WHERE username = 'marcos.vinicius'), (SELECT id FROM public.posts WHERE content = 'A @patricia.nunes quase desistiu no km 4 da primeira corrida dela. Eu tava do lado e só disse: ''Falt' LIMIT 1), 'Marcos, eu queria mesmo desistir. Mas seu jeito de não pressionar me deu coragem. Foi seu pace que me carregou.', (SELECT created_at FROM public.posts WHERE content = 'A @patricia.nunes quase desistiu no km 4 da primeira corrida dela. Eu tava do lado e só disse: ''Falt' LIMIT 1) + interval '7 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'ju.rocha'), (SELECT id FROM public.profiles WHERE username = 'vanessa.martins'), (SELECT id FROM public.posts WHERE content = 'A @ju.rocha é mãe, designer, corredora e ainda arruma tempo pra fazer mentoria com duas juniores do ' LIMIT 1), 'Van, eu falei aquilo num momento de desabafo. Mas se serviu pra alguém, fico feliz. Honestidade é o meu jeito de cuidar.', (SELECT created_at FROM public.posts WHERE content = 'A @ju.rocha é mãe, designer, corredora e ainda arruma tempo pra fazer mentoria com duas juniores do ' LIMIT 1) + interval '8 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'maria.helena'), (SELECT id FROM public.profiles WHERE username = 'jorge.ribeiro'), (SELECT id FROM public.posts WHERE content = 'A @maria.helena escreveu um poema pro aniversário do meu neto. Ela nem conhece ele pessoalmente — co' LIMIT 1), 'Jorge, escrever sobre o Bento foi como escrever sobre meu próprio neto. Suas histórias me chegam. ❤️', (SELECT created_at FROM public.posts WHERE content = 'A @maria.helena escreveu um poema pro aniversário do meu neto. Ela nem conhece ele pessoalmente — co' LIMIT 1) + interval '9 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'diego.design'), (SELECT id FROM public.profiles WHERE username = 'thiago.costa'), (SELECT id FROM public.posts WHERE content = 'Eu ia apagar uma mensagem no Slack porque achei que era boba demais. O @diego.design leu antes e res' LIMIT 1), 'Thiago, ideia boa não pode morrer no rascunho. Que bom que segurei essa.', (SELECT created_at FROM public.posts WHERE content = 'Eu ia apagar uma mensagem no Slack porque achei que era boba demais. O @diego.design leu antes e res' LIMIT 1) + interval '6 hours');
INSERT INTO public.feedbacks (mentioned_user_id, author_id, post_id, content, created_at)
VALUES
    ((SELECT id FROM public.profiles WHERE username = 'vanessa.martins'), (SELECT id FROM public.profiles WHERE username = 'dona.lucia'), (SELECT id FROM public.posts WHERE content = 'Essa moça, a @vanessa.martins — me ligou dia desses pra saber se eu tava conseguindo mexer no app no' LIMIT 1), 'Dona Lúcia, a senhora foi a pessoa mais importante do mundo naquele momento mesmo. Banco é confuso pra todo mundo. Mas a senhora aprendeu rápido!', (SELECT created_at FROM public.posts WHERE content = 'Essa moça, a @vanessa.martins — me ligou dia desses pra saber se eu tava conseguindo mexer no app no' LIMIT 1) + interval '12 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'carlos.henrique'), (SELECT id FROM public.profiles WHERE username = 'rafael.mendes'), (SELECT id FROM public.posts WHERE content = 'O @carlos.henrique mandou mensagem no grupo de pais da escola perguntando se alguém tinha um colchão' LIMIT 1), 'Rafa, era uma família que precisava de ajuda. A gente tinha o que dar. Não tem mérito.', (SELECT created_at FROM public.posts WHERE content = 'O @carlos.henrique mandou mensagem no grupo de pais da escola perguntando se alguém tinha um colchão' LIMIT 1) + interval '7 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'ana.beatriz'), (SELECT id FROM public.profiles WHERE username = 'camila.santos'), (SELECT id FROM public.posts WHERE content = 'No treino de sábado a @ana.beatriz tava claramente num dia ruim. Mais lenta, sem energia, quase chor' LIMIT 1), 'Cami, você ficou e isso foi tudo. ''Obrigada por ficar'' é a frase mais importante que eu disse esse mês.', (SELECT created_at FROM public.posts WHERE content = 'No treino de sábado a @ana.beatriz tava claramente num dia ruim. Mais lenta, sem energia, quase chor' LIMIT 1) + interval '6 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'edson.pereira'), (SELECT id FROM public.profiles WHERE username = 'pedro.augusto'), (SELECT id FROM public.posts WHERE content = 'O @edson.pereira me contou que jogava no campinho do bairro dele quando era moleque — descalço, bola' LIMIT 1), 'Pedro, aquele gol foi sorte. Mas o amor pela bola é o que carrega. Continua jogando. Sempre.', (SELECT created_at FROM public.posts WHERE content = 'O @edson.pereira me contou que jogava no campinho do bairro dele quando era moleque — descalço, bola' LIMIT 1) + interval '9 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'marcos.vinicius'), (SELECT id FROM public.profiles WHERE username = 'renata.campos'), (SELECT id FROM public.posts WHERE content = 'Obrigada @marcos.vinicius por ter me esperado no km 38 da maratona quando minhas pernas travaram. Vo' LIMIT 1), 'Renata, eu fiquei porque queria ficar. E porque no km 38, quando suas pernas param, é a cabeça que decide. A sua decidiu continuar. Eu só fiz companhia.', (SELECT created_at FROM public.posts WHERE content = 'Obrigada @marcos.vinicius por ter me esperado no km 38 da maratona quando minhas pernas travaram. Vo' LIMIT 1) + interval '3 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'camila.santos'), (SELECT id FROM public.profiles WHERE username = 'fernanda.lima'), (SELECT id FROM public.posts WHERE content = 'A @camila.santos encontrou um bug em produção sexta às 17h. Todo mundo tava já saindo. Ela não só re' LIMIT 1), 'Fer, sexta às 17h achei que ninguém ia ver. Obrigada por celebrar isso. Deu sentido.', (SELECT created_at FROM public.posts WHERE content = 'A @camila.santos encontrou um bug em produção sexta às 17h. Todo mundo tava já saindo. Ela não só re' LIMIT 1) + interval '6 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'edson.pereira'), (SELECT id FROM public.profiles WHERE username = 'seu.antonio'), (SELECT id FROM public.posts WHERE content = 'O @edson.pereira me levou no médico segunda-feira. Eu podia ter ido de ônibus, mas ele fez questão. ' LIMIT 1), 'Antônio, ônibus eu já dirigi a vida toda. Não ia deixar o senhor pegar um. Café no fim foi bônus.', (SELECT created_at FROM public.posts WHERE content = 'O @edson.pereira me levou no médico segunda-feira. Eu podia ter ido de ônibus, mas ele fez questão. ' LIMIT 1) + interval '8 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'lucas.ferreira'), (SELECT id FROM public.profiles WHERE username = 'carlos.henrique'), (SELECT id FROM public.posts WHERE content = 'O @lucas.ferreira fez o primeiro deploy dele em produção hoje. Sozinho. Sem ninguém segurando a mão.' LIMIT 1), 'Carlos, eu li isso umas 5 vezes. ''Virar desnecessário''. É isso. Obrigado por tudo, cara. De verdade.', (SELECT created_at FROM public.posts WHERE content = 'O @lucas.ferreira fez o primeiro deploy dele em produção hoje. Sozinho. Sem ninguém segurando a mão.' LIMIT 1) + interval '2 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'jorge.ribeiro'), (SELECT id FROM public.profiles WHERE username = 'dona.lucia'), (SELECT id FROM public.posts WHERE content = 'Eu e o @jorge.ribeiro fomos vizinhos por 25 anos antes dele se mudar pra Santos. Sabe o que eu mais ' LIMIT 1), 'Lúcia, vou voltar a passar buzinando, prometo. A senhora me faz lembrar que ainda sou parte daí.', (SELECT created_at FROM public.posts WHERE content = 'Eu e o @jorge.ribeiro fomos vizinhos por 25 anos antes dele se mudar pra Santos. Sabe o que eu mais ' LIMIT 1) + interval '7 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'camila.santos'), (SELECT id FROM public.profiles WHERE username = 'diego.design'), (SELECT id FROM public.posts WHERE content = 'A @camila.santos fez uma coisa que ninguém mais faz: ela testou meu protótipo como usuária real, não' LIMIT 1), 'Diego, testar como gente é melhor do que testar como QA mesmo. A gente desiste de coisas todo dia. Era pra você saber.', (SELECT created_at FROM public.posts WHERE content = 'A @camila.santos fez uma coisa que ninguém mais faz: ela testou meu protótipo como usuária real, não' LIMIT 1) + interval '7 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'patricia.nunes'), (SELECT id FROM public.profiles WHERE username = 'vanessa.martins'), (SELECT id FROM public.posts WHERE content = 'Conheci a @patricia.nunes numa corrida e descobri que ela é professora de história. A gente começou ' LIMIT 1), 'Van, conversar com você é remédio. A gente nunca sabe se a corrida foi pelos km ou pelo papo. Bora repetir.', (SELECT created_at FROM public.posts WHERE content = 'Conheci a @patricia.nunes numa corrida e descobri que ela é professora de história. A gente começou ' LIMIT 1) + interval '6 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'vanessa.martins'), (SELECT id FROM public.profiles WHERE username = 'ricardo.alves'), (SELECT id FROM public.posts WHERE content = 'A @vanessa.martins discordou de mim numa reunião. Na frente de todo mundo. Com argumentos. E tava ce' LIMIT 1), 'Ricardo, discordar de você é seguro. É isso que faz a equipe funcionar. Obrigada por aceitar a discussão.', (SELECT created_at FROM public.posts WHERE content = 'A @vanessa.martins discordou de mim numa reunião. Na frente de todo mundo. Com argumentos. E tava ce' LIMIT 1) + interval '7 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'jorge.ribeiro'), (SELECT id FROM public.profiles WHERE username = 'maria.helena'), (SELECT id FROM public.posts WHERE content = 'O @jorge.ribeiro consertou o portão da minha casa semana passada. Tem 76 anos e veio com a caixa de ' LIMIT 1), 'Helena, café com a senhora vale mais que dinheiro. Pode chamar quando precisar de qualquer outra coisa. ☕', (SELECT created_at FROM public.posts WHERE content = 'O @jorge.ribeiro consertou o portão da minha casa semana passada. Tem 76 anos e veio com a caixa de ' LIMIT 1) + interval '6 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'renata.campos'), (SELECT id FROM public.profiles WHERE username = 'thiago.costa'), (SELECT id FROM public.posts WHERE content = 'A @renata.campos fez uma coisa na retro que eu nunca tinha visto uma gestora fazer: ela admitiu que ' LIMIT 1), 'Thiago, errei mesmo. E queria que vocês soubessem. Saúde organizacional começa no líder admitir.', (SELECT created_at FROM public.posts WHERE content = 'A @renata.campos fez uma coisa na retro que eu nunca tinha visto uma gestora fazer: ela admitiu que ' LIMIT 1) + interval '7 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'camila.santos'), (SELECT id FROM public.profiles WHERE username = 'ana.beatriz'), (SELECT id FROM public.posts WHERE content = 'Preciso agradecer a @camila.santos por ter corrido do meu lado sábado quando eu tava num dia péssimo' LIMIT 1), 'Ana, ficar foi fácil. Difícil é a gente saber quando NÃO falar. Pratiquei muito pra aprender.', (SELECT created_at FROM public.posts WHERE content = 'Preciso agradecer a @camila.santos por ter corrido do meu lado sábado quando eu tava num dia péssimo' LIMIT 1) + interval '6 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'ricardo.alves'), (SELECT id FROM public.profiles WHERE username = 'lucas.ferreira'), (SELECT id FROM public.posts WHERE content = 'O @ricardo.alves me disse uma frase outro dia que eu colei no monitor: ''Você não precisa saber tudo,' LIMIT 1), 'Lucas, eu pergunto no Stack Overflow porque o Google é meu chefe. Curiosidade é vitamina, não só ferramenta. ✨', (SELECT created_at FROM public.posts WHERE content = 'O @ricardo.alves me disse uma frase outro dia que eu colei no monitor: ''Você não precisa saber tudo,' LIMIT 1) + interval '5 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'dona.lucia'), (SELECT id FROM public.profiles WHERE username = 'jorge.ribeiro'), (SELECT id FROM public.posts WHERE content = 'A @dona.lucia manda foto de bolo pra mim toda semana. Não é pra me fazer inveja — é pra eu sentir qu' LIMIT 1), 'Jorge, a foto é pra você se lembrar do cheiro de casa. Fica longe quanto quiser, mas não fica de longe. ❤️', (SELECT created_at FROM public.posts WHERE content = 'A @dona.lucia manda foto de bolo pra mim toda semana. Não é pra me fazer inveja — é pra eu sentir qu' LIMIT 1) + interval '5 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'thiago.costa'), (SELECT id FROM public.profiles WHERE username = 'edson.pereira'), (SELECT id FROM public.posts WHERE content = 'O @thiago.costa me chamou de ''mestre'' na pelada outro dia. Eu ri. Mas depois pensei: esse moleque tr' LIMIT 1), 'Senhor Edson, meus pais vão amar saber que o senhor reparou. Educação se aprende ouvindo gente como o senhor.', (SELECT created_at FROM public.posts WHERE content = 'O @thiago.costa me chamou de ''mestre'' na pelada outro dia. Eu ri. Mas depois pensei: esse moleque tr' LIMIT 1) + interval '7 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'fernanda.lima'), (SELECT id FROM public.profiles WHERE username = 'camila.santos'), (SELECT id FROM public.posts WHERE content = 'A @fernanda.lima tem um dom que eu invejo: ela pega dados frios e transforma em histórias que conven' LIMIT 1), 'Cami, dado é gente. Sempre foi. Que bom que tô conseguindo contar a história certa.', (SELECT created_at FROM public.posts WHERE content = 'A @fernanda.lima tem um dom que eu invejo: ela pega dados frios e transforma em histórias que conven' LIMIT 1) + interval '7 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'seu.antonio'), (SELECT id FROM public.profiles WHERE username = 'pedro.augusto'), (SELECT id FROM public.posts WHERE content = 'Uma vez o @seu.antonio me ensinou a afiar faca com pedra. Eu, um DevOps que não sabe pregar prego, a' LIMIT 1), 'Pedro, faca afia com pedra mas amizade afia com tempo. A gente afiou as duas naquela tarde. 🪵', (SELECT created_at FROM public.posts WHERE content = 'Uma vez o @seu.antonio me ensinou a afiar faca com pedra. Eu, um DevOps que não sabe pregar prego, a' LIMIT 1) + interval '12 hours'),
    ((SELECT id FROM public.profiles WHERE username = 'fernanda.lima'), (SELECT id FROM public.profiles WHERE username = 'renata.campos'), (SELECT id FROM public.posts WHERE content = 'Quero reconhecer algo que a @fernanda.lima fez discretamente: ela montou um doc com todos os process' LIMIT 1), 'Renata, onboarding caótico me incomodava. Ninguém merece chegar sem mapa. Ainda tem coisa pra documentar, mas começou.', (SELECT created_at FROM public.posts WHERE content = 'Quero reconhecer algo que a @fernanda.lima fez discretamente: ela montou um doc com todos os process' LIMIT 1) + interval '6 hours');
